'Online_Store_Accounts' => 'Online-Shop-Konten',
'Customers_without_login_alert' => 'Dies sind Ihre POS-/Laufkunden, die noch kein Online-Shop-Konto haben. Verwenden Sie „Konto registrieren“, um einen Shop-Login (E-Mail + Passwort) anzulegen, damit sich der Kunde anmelden und in Ihrem Online-Shop einkaufen kann.',
'Customers_with_login_alert' => 'Diese Kunden haben ein Online-Shop-Konto und können sich in Ihrem Shop anmelden. Hier vorgenommene Änderungen (E-Mail, Passwort, Status, gesperrt) betreffen nur ihren Online-Shop-Login – nicht ihren POS-Kundendatensatz.',
