'Resize_Product_Images_Help' => 'Produkt-, Varianten- und Galeriebilder beim Speichern verkleinern. Deaktivieren Sie dies, um hochgeladene Dateien in ihrer Originalauflösung zu speichern (größere Dateien, langsamere Seiten).',
'Product_Image_Max_Size' => 'Maximale Produktbildgröße',
'Product_Image_Max_Size_Help' => 'Längste Kante in Pixeln, in die gespeicherte Produktbilder eingepasst werden. Das Seitenverhältnis bleibt erhalten und kleinere Bilder werden nie vergrößert.',

