'Units_Guide_Title' => 'So funktionieren Einheiten',
'Units_Guide_Base' => 'Basiseinheit: Lassen Sie „Basiseinheit“ leer. Der Bestand wird immer in dieser Einheit gezählt, zum Beispiel Stück.',
'Units_Guide_Sub' => 'Untereinheit: Wählen Sie eine „Basiseinheit“ und verwenden Sie dann „Operator“ und „Operationswert“, um sie in diese Basiseinheit umzurechnen.',
'Units_Guide_Example_Multiply' => 'Beispiel: ein Karton mit Basiseinheit Stück, Operator * und Wert 12. Der Verkauf von 1 Karton entnimmt 12 Stück aus dem Bestand.',
'Units_Guide_Example_Divide' => 'Beispiel: ein Gramm mit Basiseinheit Kilogramm, Operator / und Wert 1000. Der Verkauf von 500 Gramm entnimmt 0,5 Kilogramm aus dem Bestand.',
'Units_Guide_Note' => 'Nur Basiseinheiten können als „Basiseinheit“ gewählt werden, und eine Einheit kann nicht gelöscht werden, solange Untereinheiten sie noch verwenden.',

'Amount_Paid' => 'Bezahlter Betrag',
'Payment_Amounts_Help' => 'Der bezahlte Betrag begleicht den Saldo und verringert den offenen Betrag. Der erhaltene Betrag ist das übergebene Bargeld: Er dient nur zur Berechnung des Wechselgelds und ändert den offenen Betrag nicht.',

'Show_Tax_Desc' => 'Die auf den gesamten Verkauf an der Kasse angewendete Steuer, gedruckt als eigene Zeile „Bestellsteuer“ in den Summen.',
'Show_Items_Tax_Desc' => 'Die Summe der eigenen Steuern jedes Produkts, gedruckt als Zeile „Gesamtsteuer Artikel“. Wenn aktiviert, wird die Zwischensumme ohne diese Steuern angezeigt.',
'Show_Discount_Desc' => 'Der auf den gesamten Verkauf angewendete Rabatt (einschließlich eines Punkterabatts), gedruckt als eigene Zeile in den Summen.',
'Show_Product_Discount_Desc' => 'Der eigene Rabatt jedes Produkts, gedruckt unter dem jeweiligen Produkt in der Artikelliste.',

'Receipt_Font_Family' => 'Beleg-Schriftart',
'Receipt_Font_Family_Desc' => 'Schriftart für den gesamten Text auf dem gedruckten Beleg. „Standard“ behält die üblichen Belegschriftarten bei.',
'Receipt_Font_Size' => 'Beleg-Schriftgröße (px)',
'Receipt_Font_Size_Desc' => 'Textgröße auf dem gesamten Beleg, von 8 bis 24 Pixel. Leer lassen, um die Standardgröße beizubehalten.',
'Font_Default' => 'Standard',

'Amount_Paid_Help' => 'Der auf dieses Dokument angewendete Betrag; er verringert den verbleibenden offenen Betrag.',
