'Warehouses_Tab_Help' => 'Verwalten Sie Ihre Lager (Geschäfte/Filialen). Jedes Lager führt seinen eigenen Bestand, und jedes Dokument — Verkäufe, Einkäufe, Umlagerungen, Bestandskorrekturen — wird einem davon zugeordnet.',
'Warehouse_Locations_Tab_Help' => 'Legen Sie Regal-/Fachplätze innerhalb jedes Lagers fest (z. B. Gang 2 – Regal B). Weisen Sie sie Produkten zu, um anzuzeigen, wo Artikel physisch gelagert sind.',
