'Enable_Pos_Salesperson_Switch' => 'Verkäufer beim Bezahlvorgang wechseln',
'Enable_Pos_Salesperson_Switch_Hint' => 'Eine Verkäuferauswahl im POS-Bildschirm anzeigen, damit ein Verkauf einem anderen Mitarbeiter zugeordnet werden kann, ohne sich abzumelden. Der ausgewählte Verkäufer wird auf der Rechnung gespeichert und in Verkaufsberichten verwendet; die aktive POS-Sitzung bleibt unverändert.',

'Wallet_Payment_Method_Missing' => 'Zahlungsmethode „Wallet“ fehlt',
'Wallet_Payment_Method_Missing_Help' => 'Es wurde keine Zahlungsmethode mit genau dem Namen „Wallet“ gefunden. Die Wallet-Zahlungsart im POS wird über diesen Namen zugeordnet, daher können Kunden erst mit ihrer Wallet bezahlen, wenn Sie hier eine Zahlungsmethode mit dem Namen „Wallet“ hinzufügen:',

'Show_Previous_Dues_Line' => 'Zeile „Vorherige offene Beträge“ anzeigen',
'Show_Previous_Dues_Line_Desc' => 'Saldo, den der Kunde vor diesem Verkauf schuldete. Wird nur gedruckt, wenn er größer als null ist.',
'Show_Net_Balance_Line' => 'Zeile „Nettosaldo“ anzeigen',
'Show_Net_Balance_Line_Desc' => 'Vorherige offene Beträge plus der noch offene Betrag dieses Verkaufs. Wird nur gedruckt, wenn die vorherigen offenen Beträge größer als null sind.',

'QZ_Tray_Printer' => 'QZ Tray (Drucker an diesem Computer)',
'QZ_Printer_Name_Hint' => 'Der Druckername, wie er auf dem Computer erscheint, auf dem QZ Tray läuft. Leer lassen, um den Standarddrucker dieses Computers zu verwenden. Klicken Sie auf ⟳, um Drucker zu erkennen.',
'QZ_Not_Running' => 'QZ Tray läuft auf diesem Computer nicht. Installieren Sie es von qz.io, lassen Sie es laufen und erlauben Sie dann diese Website, wenn QZ danach fragt.',
'Detect_Printers' => 'Drucker erkennen',
'QZ_Download_Cert' => 'Zertifikat herunterladen (override.crt)',
'QZ_Setup_Title' => 'So richten Sie den Druck mit QZ Tray ein (einmalig, auf jedem Computer, der Etiketten druckt)',
'QZ_Step_Install' => '1. Installieren Sie QZ Tray auf diesem Computer — laden Sie es kostenlos von qz.io herunter, starten Sie es und lassen Sie es laufen (es befindet sich unter Windows im Infobereich der Taskleiste bzw. unter macOS in der Menüleiste).',
'QZ_Step_Connect' => '2. Schließen Sie Ihren Etikettendrucker per USB an und prüfen Sie, ob er im Betriebssystem installiert ist (Windows: Einstellungen > Drucker & Scanner — macOS: Systemeinstellungen > Drucker & Scanner).',
'QZ_Step_Detect' => '3. Klicken Sie oben auf die Schaltfläche ⟳ neben „Druckername“, um die Drucker auf diesem Computer zu erkennen, und wählen Sie dann Ihren Etikettendrucker aus. Lassen Sie das Feld leer, um den Standarddrucker des Computers zu verwenden.',
'QZ_Step_Cert' => '4. Um ohne Berechtigungs-Pop-up zu drucken, laden Sie das untenstehende Zertifikat herunter und kopieren Sie es, umbenannt in override.crt, in den Installationsordner von QZ Tray (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Beenden Sie QZ Tray anschließend und starten Sie es neu.',
'QZ_Step_Test' => '5. Klicken Sie unten auf „Testetikett drucken“. Wenn QZ Tray um Erlaubnis bittet, klicken Sie auf Zulassen — mit installiertem Zertifikat wird nicht erneut gefragt.',
'QZ_Step_Save' => '6. Klicken Sie auf Absenden, um diese Einstellungen zu speichern. Etiketten von der Seite „Barcode drucken“ werden nun direkt auf diesem Drucker gedruckt, ohne Druckdialog des Browsers.',
'QZ_Setup_Note' => 'QZ Tray läuft auf dem Computer, von dem aus Sie surfen, daher funktioniert dies auch, wenn Stocky auf einem entfernten Server gehostet wird. Jeder Computer, der Etiketten druckt, benötigt eine QZ-Tray-Installation.',

// PWA settings tab — installable app identity
'PWA_Enabled' => 'Installierbare App aktivieren',
'PWA_Enabled_Help' => 'Ermöglicht Browsern, die Installation dieser App auf Smartphones, Tablets und Desktops anzubieten, und hält Offline-Seiten im Cache. Bei Deaktivierung wird die Installationsaufforderung überall entfernt und der Cache beim nächsten Besuch geleert.',
'PWA_Identity' => 'App-Identität',
'PWA_Launch' => 'Start & Darstellung',
'PWA_App_Name' => 'App-Name',
'PWA_App_Name_Help' => 'Wird in der Installationsaufforderung und in der App-Liste angezeigt. Leer lassen, um den App-Namen aus den Darstellungseinstellungen zu verwenden.',
'PWA_Short_Name' => 'Kurzname',
'PWA_Short_Name_Help' => 'Wird unter dem Symbol auf Startbildschirmen angezeigt, wo lange Namen abgeschnitten werden. Leer lassen, um den Teil des App-Namens vor dem „|“ zu verwenden.',
'PWA_Description' => 'Beschreibung',
'PWA_Description_Help' => 'Wird von einigen App-Stores und Installationsdialogen angezeigt.',
'PWA_Start_Url' => 'Startseite',
'PWA_Start_Url_Help' => 'Die Seite, auf der die installierte App geöffnet wird, als Pfad, der mit „/“ beginnt. Verwenden Sie /next/pos, um direkt im POS zu starten.',
'PWA_Display_Mode' => 'Anzeigemodus',
'PWA_Display_Mode_Help' => 'standalone blendet die Browserleiste aus; fullscreen blendet zusätzlich die Statusleiste aus; browser öffnet einen normalen Tab.',
'PWA_Orientation' => 'Ausrichtung',
'PWA_Theme_Color' => 'Designfarbe',
