'PWA_Reinstall_Notice' => 'Geräte, auf denen die App bereits installiert ist, behalten den alten Namen und das alte Symbol, bis die App deinstalliert und erneut installiert wird.',

'Label_Render_Mode' => 'Etikettendarstellung',
'Label_Render_Mode_Hint' => 'Wie das Etikett gezeichnet wird. Druckerschriften ist am schnellsten und liefert den schärfsten Barcode, druckt aber nur einfache lateinische Zeichen in der druckereigenen Schrift. Vorschaubild gibt Ihr Etikettendesign exakt wieder — Ihre gewählte Schriftart, jede Sprache — so wie spezielle Etikettensoftware.',
'Render_Native' => 'Druckerschriften (am schnellsten)',
'Render_Raster' => 'Vorschaubild (exaktes Design)',
'Label_Width_Mm' => 'Etikettenbreite (mm)',
'Label_Height_Mm' => 'Etikettenhöhe (mm)',
'Label_Size_Hint' => 'Die physische Größe eines Aufklebers auf der Rolle. Sie muss exakt mit den eingelegten Etiketten übereinstimmen — eine falsche Größe lässt den Drucker an der falschen Stelle nach dem Abstand suchen, sodass jedes Etikett weiter versetzt gedruckt wird.',
'Calibrate_Labels' => 'Etiketten kalibrieren',
'Calibrate_Labels_Hint' => 'Der Drucker zieht einige Etiketten ein, um Aufkleber und Abstand zu messen. Einmal nach dem Einlegen einer neuen Rolle ausführen oder wenn die Druckpositionen abweichen.',
'Calibration_Sent' => 'Kalibrierung gestartet — der Drucker zieht einige leere Etiketten zum Messen ein. Wenn er stoppt, führen Sie einen Testdruck aus.',
'Label_Printer_Dpi' => 'Druckkopfauflösung',
'Label_Printer_Dpi_Hint' => 'Die meisten Etikettendrucker haben 203 dpi. Nicht sicher? Verwenden Sie unten die Schaltfläche „Auflösung ermitteln“ — sie druckt die Antwort aus.',
'Find_Resolution' => 'Auflösung ermitteln',
'Find_Resolution_Hint' => 'Druckt zwei Etiketten, markiert mit 203 und 300. Das richtige zeigt ein vollständiges Rechteck auf dem Aufkleber mit einem kleinen, gleichmäßigen Rand an allen vier Seiten; beim falschen fehlen Ränder oder es läuft auf den nächsten Aufkleber über.',
'Dpi_Test_Sent' => 'Zwei Etiketten werden gedruckt, markiert mit 203 und 300. Das richtige zeigt ein vollständiges Rechteck mit einem kleinen, gleichmäßigen Rand an allen vier Seiten — stellen Sie „Druckkopfauflösung“ auf diese Zahl ein und speichern Sie.',
'Label_Offset_X' => 'Horizontaler Versatz (mm)',
'Label_Offset_X_Hint' => 'Verschiebt den Druck seitlich auf dem Aufkleber. Verwenden Sie dies, wenn Text an einem Seitenrand abgeschnitten wird — z. B. 2.5, wenn der weiße Aufkleber mittig auf einem breiteren Trägerpapier sitzt. In 0.5-Schritten anpassen.',
'Label_Offset_Y' => 'Vertikaler Versatz (mm)',
'Label_Offset_Y_Hint' => 'Verschiebt den Druck entlang des Etiketts. Erhöhen, wenn der obere Teil des Designs abgeschnitten ist oder fehlt; verringern, wenn er zu weit unten beginnt.',
'Feed_To_Tear' => 'Bis zur Abreißkante vorschieben',
'Feed_To_Tear_Hint' => 'Schiebt das Etikett nach jedem Auftrag bis zur Abreißkante vor. Lassen Sie dies AUS, wenn Etiketten nach unten versetzt oder über zwei Aufkleber verteilt gedruckt werden — viele Drucker fahren vor dem nächsten Etikett nicht zurück.',
