/* ---- Online orders guide (Store > Online Orders) ---- */
'Orders_Guide' => 'Bestellungs-Leitfaden',
'Ord_Guide_Intro' => 'Wie eine in Ihrem Online-Shop aufgegebene Bestellung in Ihren Bestand und Ihre Konten gelangt und wo das Geld tatsächlich erfasst wird.',
'Ord_Guide_Lifecycle_Title' => 'Bestellstatus',
'Ord_Guide_Lifecycle_Pending' => 'Eine neue Bestellung, die auf Ihre Prüfung wartet. Nur eine ausstehende Bestellung kann bestätigt oder storniert werden.',
'Ord_Guide_Lifecycle_Confirmed' => 'Sie haben die Bestellung angenommen. Stocky erstellt einen Verkauf im ausgewählten Lager und bucht den Bestand ab — dieser Verkauf ist der Datensatz, aus dem Ihre Bestands-, Zahlungs- und Gewinnberichte lesen.',
'Ord_Guide_Lifecycle_Shipped' => 'Sie haben die Bestellung versendet. Nur Abwicklung: Der Bestand wurde bereits bei der Bestätigung abgebucht.',
'Ord_Guide_Lifecycle_Delivered' => 'Der Kunde hat die Bestellung erhalten. Damit beginnt die Rückgabefrist.',
'Ord_Guide_Lifecycle_Cancelled' => 'Die Bestellung wurde vor der Bestätigung verworfen, daher wurde kein Verkauf erstellt und kein Bestand abgebucht.',
'Ord_Guide_PaymentStatus_Tip' => 'Wird beim Bezahlvorgang festgelegt und kann hier nicht bearbeitet werden. Klicken Sie, um zu sehen, wie die Zahlung erfasst wird.',
'Ord_Guide_Payment_Title' => 'Zahlungsstatus',
'Ord_Guide_Payment_Intro' => 'Diese Spalte zeigt, wie der Kunde beim Bezahlvorgang bezahlen wollte. Sie wird vom Shop festgelegt und kann auf dieser Seite nicht bearbeitet werden — das Geld selbst wird auf dem Verkauf erfasst, der durch die Bestätigung der Bestellung entsteht.',
'Ord_Guide_Payment_Paid' => 'Der Kunde hat bereits online über ein Zahlungs-Gateway bezahlt. Die Bestätigung der Bestellung erstellt den Verkauf als Bezahlt und erfasst die Zahlung für Sie — sonst ist nichts zu tun.',
'Ord_Guide_Payment_Pending' => 'Nachnahme, Banküberweisung oder eine andere Methode mit späterer Zahlung. Die Bestätigung der Bestellung erstellt den Verkauf als Unbezahlt, daher erfassen Sie das Geld selbst, sobald Sie es erhalten haben — siehe die Schritte unten.',
'Ord_Guide_Payment_Failed' => 'Das Gateway hat die Zahlung abgelehnt oder der Kunde hat sie abgebrochen. Die Bestellung wird automatisch storniert.',
'Ord_Guide_MarkPaid_Title' => 'Zahlung von ausstehend auf bezahlt ändern',
'Ord_Guide_MarkPaid_Step1' => 'Bestätigen Sie die Bestellung zuerst hier — erst die Bestätigung erstellt den Verkauf.',
'Ord_Guide_MarkPaid_Step2' => 'Öffnen Sie Verkäufe > Alle Verkäufe und suchen Sie diesen Verkauf (gleicher Kunde; die Detailseite zeigt die Online-Bestellung, aus der er stammt).',
'Ord_Guide_MarkPaid_Step3' => 'Öffnen Sie das Aktionsmenü der Zeile und wählen Sie Zahlung erstellen.',
'Ord_Guide_MarkPaid_Step4' => 'Geben Sie Betrag, Zahlungsmethode und Datum ein und speichern Sie. Der Verkauf wechselt je nach Betrag automatisch auf Teilweise oder Bezahlt.',
'Ord_Guide_MarkPaid_Note' => 'Der hier angezeigte Zahlungsstatus zeigt weiterhin die beim Bezahlvorgang getroffene Wahl und bleibt unverändert. Der Verkauf ist der Buchhaltungsdatensatz und speist Ihre Zahlungs- und Gewinnberichte. Verwenden Sie Zahlungen anzeigen beim Verkauf, um Ihre Eingaben zu prüfen oder zu bearbeiten.',
'Ord_Guide_Notes_Title' => 'Gut zu wissen',
'Ord_Guide_Note_Warehouse' => 'Das Lager, das Sie bei der Bestätigung auswählen, bestimmt, woher der Bestand entnommen wird. Lager, die nicht die gesamte Bestellung abdecken können, sind in dieser Liste als Nicht vorrätig markiert.',
'Ord_Guide_Note_Preorder' => 'Vorbestellungsartikel überspringen die Bestandsprüfung, daher kann eine Bestellung mit solchen Artikeln bestätigt werden, auch wenn die Menge noch nicht vorrätig ist.',
'Ord_Guide_Note_Flagged' => 'Eine Markierung „Markiert“ bedeutet, dass die Bestellung beim Bezahlvorgang eine Betrugsprüfung ausgelöst hat. Fahren Sie mit der Maus über die Markierung, um den Grund zu sehen, und prüfen Sie die Bestellung, bevor Sie sie bestätigen.',
'Ord_Guide_Note_Cancel' => 'Eine Stornierung ist nur möglich, solange die Bestellung noch aussteht. Nach der Bestätigung machen Sie sie stattdessen über den Verkauf oder eine Kundenretoure rückgängig.',


