'Warehouse_Letterhead_Receipt_Notice' => 'Der Lager-Briefkopf ist aktiviert: Shopname, Adresse und Telefonnummer auf einem echten Beleg stammen vom Lager, das den Verkauf ausgestellt hat, und dessen Fußzeilenhinweis wird unter dem Kundenhinweis ergänzt.',
