'Set_Follow_Device' => 'Geräteeinstellung folgen',
'Set_Returns' => 'Retouren',
'Set_Todays_Sales' => 'Heutige Verkäufe',
'Set_Sort' => 'Sortieren',
'Set_Audit_Log' => 'Audit-Protokoll',
'Set_Qb_Synced_N_Clients' => '{n} Kunden synchronisiert',
'Set_Qb_Synced_N_Selected' => '{n} ausgewählte synchronisiert',
'Set_Subscription_Reminder' => 'Abonnement-Erinnerung',
'Upd_Note_Code_Changes_Lost' => 'Hinweis 1: Wenn Sie den Code manuell geändert haben, gehen Ihre Änderungen verloren.',
'Upd_Manual_Steps_Intro' => 'Bitte folgen Sie diesen Schritten, um Ihre Anwendung zu aktualisieren',
'Upd_Note_Permission_Only' => 'Hinweis 2: Nur ein Administrator oder ein Benutzer mit der Berechtigung „{perm}“ kann das System aktualisieren',
'Upd_Manual_Step_Backup_Db' => 'Erstellen Sie ein Backup Ihrer Datenbank. Gehen Sie zu {backup} und klicken Sie auf „Backup erstellen“ — Sie finden es unter {path} — oder exportieren Sie Ihre Datenbank aus PhpMyAdmin und speichern Sie sie auf Ihrem PC.',
'Upd_Manual_Step_Backup_Files' => 'Erstellen Sie vor dem Update ein Backup Ihrer Dateien.',
'Upd_Manual_Step_Download' => 'Laden Sie die neueste Version aus Ihrem CodeCanyon-Konto herunter und entpacken Sie sie.',
'Upd_Manual_Step_Remove' => 'Entfernen Sie die bisherigen Dateien, {except}:',
'Upd_Except' => 'außer',
'Upd_File_Label' => 'Datei: {name}',
'Upd_Folder_Label' => 'Ordner: {name}',
'Upd_Manual_Step_Reupload' => 'Laden Sie die Dateien und Ordner aus dem neuen Update erneut hoch, {except} den gleichen drei oben genannten Pfaden.',
'Upd_Manual_Step_Visit' => 'Rufen Sie {url} auf, um Ihre Datenbank zu aktualisieren.',
'Upd_Manual_Step_Clear_Cache' => 'Leeren Sie den Browser-Cache vollständig.',
'Upd_Manual_Step_Done' => 'Fertig! Viel Freude mit der aktualisierten Anwendung.',
'Upd_Note_Blank_Pages' => 'Hinweis: Wenn Seiten nicht laden oder leer sind, stellen Sie sicher, dass Sie Ihren Browser-Cache geleert haben.',
'Upd_Guide_Before_Title' => '1. Vor dem Update',
'Upd_Guide_Before_Download' => 'Laden Sie das {package} der Anwendung aus Ihrem CodeCanyon-Konto ({path}) herunter. Entpacken Sie es nicht — der Updater benötigt die ZIP-Datei genau so, wie sie heruntergeladen wurde.',
'Upd_Latest_Full_Zip' => 'neueste vollständige ZIP-Paket',
'Upd_Guide_Before_Admin' => 'Stellen Sie sicher, dass Sie als Administrator mit der Berechtigung {perm} angemeldet sind. Niemand sonst kann den Updater sehen oder ausführen.',
'Upd_Guide_Before_Quiet' => 'Wählen Sie einen ruhigen Zeitpunkt: Während des Updates wechselt die Anwendung kurzzeitig in den Wartungsmodus und andere Benutzer werden ausgesperrt.',
'Upd_Guide_Before_No_Manual' => 'Sie müssen {not} manuell sichern, Dateien entpacken, Befehle ausführen, Konfigurationsdateien bearbeiten oder die Datenbank anfassen — der Updater erledigt all das automatisch. (Ein zusätzliches manuelles Backup schadet natürlich nie.)',
'Upd_Not' => 'nicht',
'Upd_Guide_Code_Overwritten' => 'Wenn Sie den Anwendungscode manuell geändert haben, werden Ihre Änderungen durch das Update überschrieben. Ihre Daten, Uploads, Einstellungen und die .env bleiben immer erhalten.',
'Upd_Guide_Running_Title' => '2. Update ausführen',
'Upd_Guide_Run_Open' => 'Öffnen Sie {path} (diese Seite) und bleiben Sie auf dem Tab {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: Klicken Sie in das Upload-Feld oder ziehen Sie das heruntergeladene Paket hinein. Große Dateien werden in kleinen Teilen hochgeladen, daher funktioniert dies auch auf Shared Hosting mit niedrigen Upload-Limits. Eine Prüfsumme schützt vor beschädigten oder unvollständigen Uploads.',
'Upd_Upload_The_Zip' => 'ZIP-Datei hochladen',
'Upd_Guide_Run_Validation' => '{auto} nach dem Upload (Sie können sie mit der Schaltfläche {button} erneut ausführen). Das System prüft: ZIP-Integrität, Paketstruktur und Vollständigkeit, Versionskompatibilität (Downgrades werden abgelehnt), erforderliche PHP-Version und -Erweiterungen, Dateiberechtigungen, freien Speicherplatz, Datenbankverbindung, Konfiguration sowie, dass kein anderes Update läuft.',
'Upd_Validation_Runs_Automatically' => 'Die Validierung läuft automatisch',
'Upd_Guide_Run_Review' => 'Prüfen Sie den Bereich {panel}. Die Schaltfläche {button} erscheint nur, wenn alle kritischen Prüfungen bestanden sind. Schlägt eine Prüfung fehl, sagt Ihnen die Meldung genau, was zu beheben ist.',
'Upd_Guide_Run_Click' => 'Klicken Sie auf {button} und bestätigen Sie. Dann einfach {keep} und den Fortschrittsbalken beobachten. Das System führt nacheinander aus:',
'Upd_Keep_Page_Open' => 'diese Seite geöffnet lassen',
'Upd_Guide_Phase_Backup' => '{label} — ein vollständiger Datenbank-Dump, ein ZIP aller Anwendungsdateien, die das Update ändern kann, und eine Kopie von {env} werden erstellt und {verified}. Ihre Uploads ({images}) und {storage} werden von einem Update nie angetastet und daher nicht archiviert. Kann kein Backup erstellt werden, stoppt das Update hier und es wird nichts geändert.',
'Upd_Verified' => 'verifiziert',
'Upd_Guide_Phase_Prepare' => '{label} — die neue Version wird in einen Staging-Bereich entpackt und erneut validiert. Die Live-Anwendung bleibt weiterhin unberührt.',
'Upd_Guide_Phase_Maintenance' => '{label} — der Wartungsmodus wird aktiviert; Besucher sehen einen freundlichen „Wir sind gleich zurück“-Bildschirm.',
'Upd_Guide_Phase_Files' => '{label} — die neuen Dateien werden nahezu sofort eingesetzt; die alten Dateien werden für einen Rollback aufbewahrt. Geschützte Pfade ({env}, {storage}, {images}) werden nie ersetzt.',
'Upd_Guide_Phase_Database' => '{label} — Migrationen werden ausgeführt, anschließend werden Berechtigungen, Übersetzungen und Vorlagen aktualisiert.',
'Upd_Guide_Phase_Cache' => '{label} — alle Caches werden geleert und neu aufgebaut.',
'Upd_Guide_Phase_Verify' => '{label} — Integritätsprüfungen bestätigen, dass die neue Version startet, die Datenbank funktioniert, alle Migrationen ausgeführt wurden und die Konfiguration gültig ist.',
'Upd_Guide_Phase_Done' => '{label} — der Wartungsmodus wird aufgehoben und temporäre Dateien werden bereinigt.',
'Upd_Guide_Run_Success' => 'Wenn Sie {success} sehen, klicken Sie auf {reload} und aktualisieren Sie Ihren Browser vollständig ({keys}), damit die neuen Admin-Panel-Assets geladen werden.',
'Upd_Update_Successful_Short' => 'Update erfolgreich',
'Upd_Guide_No_Internet' => 'Während des Updates ist keine Internetverbindung erforderlich — alles stammt aus der hochgeladenen ZIP-Datei. Ein Verbindungsabbruch oder das Schließen des Browsers bricht das Update NICHT ab: Der Server merkt sich genau, wo er angehalten hat.',
'Upd_Guide_Wrong_Title' => '3. Wenn etwas schiefgeht',
'Upd_Guide_Wrong_Rollback' => '{label} — schlägt etwas fehl, nachdem bereits Dateien geändert wurden (Entpackfehler, fehlgeschlagene Migration, fehlgeschlagene Integritätsprüfung, voller Datenträger, …), stellt das System automatisch die vorherigen Dateien und die Datenbank aus dem verifizierten Backup wieder her, hebt den Wartungsmodus auf und meldet {message}. Sie landen genau dort, wo Sie begonnen haben.',
'Upd_Automatic_Rollback' => 'Automatischer Rollback',
'Upd_Failed_Previous_Restored' => 'Update fehlgeschlagen — vorherige Version wiederhergestellt',
'Upd_Guide_Wrong_Interrupted' => '{label} (Serverneustart, Timeout, geschlossener Browser, Stromausfall) — wenn Sie diese Seite erneut öffnen, bietet ein rotes Banner zwei sichere Optionen: {resume} (setzt genau an dem Schritt fort, an dem es angehalten hat) oder {rollback} (stellt die vorherige Version aus dem Backup wieder her).',
'Upd_Interrupted_Update' => 'Unterbrochenes Update',
'Upd_Guide_Wrong_Unreachable' => '{label} — verwenden Sie die eigenständige {console} unter {path}. Sie funktioniert auch, wenn sich die Website im Wartungsmodus befindet oder die Admin-Panel-Assets defekt sind, und bietet dieselben Aktionen Fortsetzen / Zurücksetzen. Außerdem gibt es unten auf dem Wartungsbildschirm einen unauffälligen Link „Administratorzugang“.',
'Upd_Admin_Unreachable' => 'Admin-Panel nicht erreichbar',
'Upd_Recovery_Console' => 'Wiederherstellungskonsole',
'Upd_Guide_Wrong_Locked_Out' => '{label} — während ein Update läuft, zeigt diese Seite einen {link} an. Speichern Sie ihn, falls Sie wieder hineinmüssen (zum Beispiel nach Ablauf Ihrer Sitzung); er lässt Sie am Wartungsbildschirm vorbei, damit Sie sich erneut anmelden können.',
'Upd_Locked_Out_Maintenance' => 'Durch den Wartungsmodus ausgesperrt',
'Upd_Bypass_Link' => 'Umgehungslink',
'Upd_Guide_Wrong_Concurrent' => '{label} — dieser sieht {message} Es kann immer nur ein Update gleichzeitig laufen.',
'Upd_Another_Admin_Updating' => 'Ein anderer Administrator versucht gleichzeitig zu aktualisieren',
'Upd_Guide_Backups_Title' => '4. Backups & Wiederherstellung',
'Upd_Guide_Backups_Created' => 'Jedes Update erstellt ein Backup, {before} es etwas verändert: alle Anwendungsdateien, die das Update ersetzen kann, eine Kopie von {env} und einen vollständigen Datenbank-Dump. Uploads und {storage} werden durch ein Update nie verändert und sind daher nicht enthalten — erstellen Sie dafür eigene Backups. Backups liegen in {path} und sind nie über das Web zugänglich.',
'Upd_Before' => 'bevor',
'Upd_Guide_Backups_Panel' => 'Der Bereich {panel} auf dem Tab {tab} listet sie mit Datum, Version und Größe auf. Dort können Sie jedes vollständige Backup {restore} (Dateien + Datenbank — zuvor wird eine Sicherheitskopie der aktuellen Datenbank erstellt) oder alte {delete}.',
'Upd_Restore_Verb' => 'wiederherstellen',
'Upd_Delete_Verb' => 'löschen',
'Upd_Guide_Backups_Retention' => 'Legen Sie mit {keep} fest, wie viele Backups aufbewahrt werden; ältere werden nach jedem erfolgreichen Update automatisch entfernt. Das einzige verbleibende vollständige Backup kann nie gelöscht werden — Sie haben also immer einen Weg zurück.',
'Upd_Guide_Manual_Title' => '5. Manuelles Update (Ausweichmethode)',
'Upd_Guide_Manual_Text' => 'Wenn Sie lieber von Hand aktualisieren oder der Uploader auf Ihrem Server nicht genutzt werden kann, folgen Sie der Schritt-für-Schritt-Anleitung auf dem Tab {tab} dieser Seite.',
'Upd_Guide_Clear_Cache_First' => 'Wenn Seiten nach einem Update defekt oder leer aussehen, leeren Sie zuerst Ihren Browser-Cache — das ist fast immer die Ursache.',
'Upd_Restore_Backup_Confirm' => 'Dieses Backup wiederherstellen? Die aktuellen Dateien und die aktuelle Datenbank werden durch das Backup ersetzt. Zuvor wird eine Sicherheitskopie der aktuellen Datenbank erstellt. (v{version} — {date})',
'Woo_Guide_Lead' => 'So hält sich ein WooCommerce-Shop mit dem ERP synchron. Die Cron-Zeilen unten sind für diesen Server erstellt und können direkt darauf übernommen werden.',
'Woo_Guide_Ways_Note' => 'Anders als Shopify sendet WooCommerce von sich aus nichts an das ERP — hier gibt es keinen Webhook-Empfänger, daher kommt alles, was {in} das ERP hineingeht, nach Zeitplan an. Nur Bestand, der {out} hinausgeht, kann sofort übertragen werden.',
'Woo_In' => 'in',
'Woo_Out' => 'aus dem ERP',
'Woo_Guide_Both_Ways_Title' => 'Beide Wege benötigen zuerst dies',
'Woo_Api_Keys' => 'API-Schlüssel',
'Woo_Guide_Api_Keys_Text' => '{path}, Berechtigung {perm}. Kopieren Sie Consumer Key und Secret in den Tab {settings}, zusammen mit der Shop-URL — der Adresse Ihrer Website ohne abschließenden Schrägstrich, z. B. {example}.',
'Woo_Credentials_Saved' => 'Zugangsdaten gespeichert',
'Woo_Not_Configured_Yet' => 'noch nicht konfiguriert',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress-Anwendungspasswort (optional)',
'Woo_Guide_Wp_App_Password_Text' => 'Wird nur für Produktbilder verwendet. Die WooCommerce-API überträgt Produkte, Bestand, Kategorien, Marken, Kunden und Bestellungen; die WordPress-API durchsucht die Mediathek und lädt ein Bild hoch, das dort noch nicht vorhanden ist.',
'Woo_Guide_Wp_App_Password_Note' => 'Verwenden Sie einen WordPress-Benutzer, der Medien verwalten darf, und erstellen Sie das Passwort unter {path}. Lassen Sie beide Felder leer, wird trotzdem alles synchronisiert — nur das Anhängen von Bildern entfällt.',
'Woo_Guide_Pick_Way_Title' => 'Wählen Sie dann, wie die Synchronisierung erfolgt',
'Woo_Right_Away' => 'Sofort',
'Woo_Stock_Live' => 'Bestand live',
'Woo_Stock_Not_Live' => 'Bestand nicht live',
'Woo_Guide_Realtime_Lead' => 'Nur eine Richtung: Bestand und Produkte, die das ERP verlassen. Bestellungen und Produktänderungen in WooCommerce kommen weiterhin nach Zeitplan an — siehe den anderen Tab.',
'Woo_Push_Stock_On_Change' => 'Bestand sofort bei Änderung übertragen',
'Woo_Setting_People_Miss' => 'Diese Einstellung wird häufig übersehen',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Ein POS-Verkauf erreicht WooCommerce {not} von selbst. Ist die Option deaktiviert, erfährt der Shop erst bei der nächsten Bestandssynchronisierung davon — standardmäßig nach einer Stunde — und in dieser Zeit kann er eine Einheit verkaufen, die Sie an der Kasse bereits verkauft haben.',
'Woo_Does_Not' => 'nicht',
'Woo_Guide_Tick_Instant' => 'Aktivieren Sie {option} auf dem Tab {settings}. Das ist die gesamte Einrichtung — kein Worker, kein Cron. Jeder Verkauf, jede Retoure, Bestandskorrektur, Umlagerung und jeder eingegangene Einkauf sendet dann eine Übertragung nur der betroffenen Produkte, direkt nachdem der Verkauf gespeichert wurde, und ein Verkauf mit zwanzig Positionen kostet eine Übertragung, nicht zwanzig. Die Kasse wartet nie darauf.',
'Woo_Currently' => 'Derzeit:',
'Woo_Instant_On_Text' => 'ein — Bestand wird bei Änderung übertragen',
'Woo_Instant_Off_Text' => 'aus — Bestand nur nach Zeitplan',
'Woo_Guide_Instant_Note' => 'Es werden nur Produkte übertragen, die bereits mit WooCommerce verknüpft sind — ein nie synchronisiertes Produkt hat im Shop nichts, was korrigiert werden könnte. Variable Produkte laufen über ihr Elternprodukt, und ein Kombiprodukt wird erneut übertragen, wenn sich eine seiner Komponenten ändert. Massenoperationen (Löschen eines Produkts, Zurücksetzen eines Lagers) schreiben Bestand, ohne ein Ereignis auszulösen — ein Grund, zusätzlich die stündliche Bestandssynchronisierung beizubehalten.',
'Woo_Push_Products_On_Save' => 'Produkte sofort beim Speichern übertragen',
'Woo_Guide_Tick_Auto_Products' => 'Aktivieren Sie {option} auf dem Tab {settings}, und ein in Stocky erstelltes, bearbeitetes oder dupliziertes Produkt wird direkt nach dem Speichern an WooCommerce gesendet — Details, Preis, Varianten und Bilder, danach sein Bestand. Ein neues Produkt wird sofort im Shop angelegt, statt auf die nächtliche Produktsynchronisierung zu warten.',
'Woo_On' => 'ein',
'Woo_Off' => 'aus',
'Woo_Guide_Bulk_Imports_Note' => 'Massenimporte werden nicht einzeln übertragen — führen Sie nach einem Import eine Produktsynchronisierung aus. Synchronisieren Sie zuerst Kategorien und Marken, damit ein übertragenes Produkt in der richtigen Kategorie landet.',
'Woo_Nothing_Else_To_Install' => 'Sonst muss nichts installiert werden',
'Woo_Guide_Same_Process' => 'Kein Queue-Worker, kein Cron-Eintrag. Die Übertragung läuft im selben Prozess, der den Verkauf verarbeitet hat, {after} die Antwort zurückgesendet wurde, sodass die Kasse nie auf WooCommerce wartet. Übertragungen überschneiden sich nie: Änderungen, die während einer laufenden Übertragung erfolgen, warten auf diese und werden direkt danach gesendet.',
'Woo_After' => 'nachdem',
'Woo_Guide_Shop_Stops_Answering' => 'Ein Shop, der nicht mehr antwortet, wird nach acht Sekunden aufgegeben, und Übertragungen pausieren für fünf Minuten, damit nicht jeder Verkauf erneut darauf wartet; die zwischenzeitlich eingegangenen Änderungen werden mit der ersten Übertragung nach der Pause gesendet, und die stündliche Bestandssynchronisierung holt ohnehin alles nach. Jede Pause wird im Tab „Protokolle“ festgehalten.',
'Woo_Guide_Artisan_Exception' => 'Eine Ausnahme: Eine durch einen Artisan-Befehl ausgelöste Bestandsänderung hat keine Antwort, nach der sie laufen könnte, daher wird sie stattdessen in die Queue {queue} gestellt. Damit auch diese zügig gesendet werden, arbeiten Sie diese Queue ab:',
'Woo_Cron_Line_Copied' => 'Cron-Zeile kopiert',
'Woo_Command_Copied' => 'Befehl kopiert',
'Woo_Guide_Not_Woo_Queue' => 'Bewusst nicht die Queue {queue}: Diese trägt die stundenlangen Katalog-Batches, und eine dahinter eingereihte Sofortübertragung wäre nicht mehr sofort.',
'Woo_On_A_Schedule' => 'Nach Zeitplan',
'Woo_Guide_Scheduled_Lead' => 'Alles wird in regelmäßigen Abständen in beide Richtungen erneut geprüft. So gelangen Bestellungen ins ERP, so wird ein Katalog veröffentlicht, und so wird alles repariert, was der schnelle Weg verpasst hat. Jeder Job hat seinen eigenen Cron-Eintrag, sodass Sie nur ausführen, was Sie möchten.',
'Woo_Guide_Sync_Drains_Queue' => '{command} arbeitet während der Ausführung seine eigene Queue ab, daher benötigen diese Zeilen keinen separaten Worker. Verwenden Sie unter Windows die Aufgabenplanung mit dem Programm {program} und denselben Argumenten, gestartet in {path}.',
'Woo_Or_No_Cron' => 'Oder ganz ohne Cron',
'Woo_Guide_No_Cron_Text' => 'Jeder Tab hier synchronisiert auf Anforderung, und eine manuelle Synchronisierung arbeitet ihre eigenen Batches ab, solange die Seite geöffnet ist — ein kleiner Shop kann also ganz ohne Cron-Eintrag laufen. Was Sie verlieren, ist alles, was passiert, während niemand hinschaut: Bestellungen kommen nur an, wenn jemand auf die Schaltfläche klickt.',
'Woo_Commands_Worth_Knowing' => 'Nützliche Befehle',
'Woo_Worth_Knowing' => 'Gut zu wissen',
'Woo_Guide_Changing_Url_Clears' => 'Eine Änderung der Shop-URL oder der API-Schlüssel löscht alle Zuordnungen — Produkte, Kategorien, Marken und Kunden werden dann erneut mit dem neuen Shop synchronisiert.',
'Woo_Guide_Keep_Skus' => 'Halten Sie die SKUs zwischen Stocky und WooCommerce einheitlich: Das verhindert Duplikate und macht das erneute Verknüpfen sicher.',
'Woo_Guide_Stock_Total' => 'Der an Woo übertragene Bestand ist der {total}, nicht der Wert eines einzelnen Lagers.',
'Woo_Total_Across_Warehouses' => 'Gesamtbestand über alle Lager',
'Woo_Guide_Full_Reference' => 'Die vollständige Referenz — jeder Scope, das Verhalten der Queue und eine Fehlerbehebungsliste — finden Sie in {file}.',
'Woo_Way_Covers' => 'Umfasst',
'Woo_Way_Covers_Realtime' => 'Nur Bestand, der das ERP verlässt — ein POS-Verkauf, eine Retoure, eine Bestandskorrektur, ein eingegangener Einkauf',
'Woo_Way_Covers_Scheduled' => 'Alles, in beide Richtungen: Bestellungen und Produktänderungen hinein, Katalog und Bestand hinaus',
'Woo_Way_Speed' => 'Geschwindigkeit',
'Woo_Way_Seconds' => 'Sekunden',
'Woo_Way_Speed_Scheduled' => 'Was Sie im Cron-Eintrag festlegen (Bestand stündlich, Bestellungen alle 15 Min.)',
'Woo_Way_Needs' => 'Benötigt',
'Woo_Way_Needs_Realtime' => 'Nichts — nur die Einstellung',
'Woo_Way_Needs_Scheduled' => 'Einen Cron-Eintrag pro Job — oder nichts, wenn Sie manuell synchronisieren',
'Woo_Way_Switched_On_At' => 'Aktiviert unter',
'Woo_Way_Cron_Entries_Below' => 'Die Cron-Einträge unten',
'Woo_Cron_Orders' => 'Bestellungen alle 15 Minuten — nur die seit dem letzten Lauf geänderten.',
'Woo_Cron_Products_Pull' => 'Produktänderungen aus dem Shop, jede Nacht um 03:00.',
'Woo_Cron_Customers' => 'Kunden, jede Nacht um 03:30.',
'Woo_Cron_Stock' => 'Bestand jede Stunde — das Sicherheitsnetz unter der Sofortübertragung und die einzige Bestandssynchronisierung ohne sie.',
'Woo_Cron_Products_Push' => 'Noch nicht verknüpfte Produkte, jede Nacht um 02:00. Bestehende Produkte werden nicht überschrieben.',
'Woo_Cmd_Stock' => 'Bestand für alle verknüpften Produkte jetzt übertragen.',
'Woo_Cmd_Products_Unsynced' => 'Produkte veröffentlichen, die noch keine WooCommerce-ID haben.',
'Woo_Cmd_Orders' => 'Seit dem letzten Lauf geänderte Bestellungen importieren.',
'Woo_Cmd_Orders_Full' => 'Alle Bestellungen neu durchsuchen statt nur der letzten Änderungen.',
'Woo_Cmd_Pull' => 'Alles Eingehende auf einmal: Produkte, Bestellungen, Kunden.',
'Woo_Guide_Page_Title' => 'WooCommerce-Leitfaden',
'Woo_Guide_Page_Subtitle' => 'Shop verbinden, was automatisch läuft, und die Cron-Einträge für diesen Server',
'Woo_Settings_Button' => 'WooCommerce-Einstellungen',
'Woo_No_Shop_Connected' => 'Es ist noch kein Shop verbunden',
'Woo_No_Shop_Connected_Desc' => 'Alles Folgende gilt trotzdem — geben Sie die Shop-URL und die API-Schlüssel auf der Seite WooCommerce-Einstellungen ein und kommen Sie dann zurück.',
'Woo_Wp_Username' => 'WordPress-Benutzername',
'Woo_Wp_App_Password' => 'WordPress-Anwendungspasswort',
'Woo_Settings_Instant_Hint' => 'Ein Verkauf, eine Retoure oder eine Bestandskorrektur sendet in dem Moment, in dem sie gespeichert wird, eine Bestandsübertragung nur für die betroffenen Produkte, sodass der Shop innerhalb von Sekunden stimmt statt erst bei der nächsten stündlichen Bestandssynchronisierung. Sonst muss nichts installiert werden — die Übertragung läuft, nachdem der Verkauf beantwortet wurde, sodass die Kasse nie auf WooCommerce wartet. Mehr dazu auf dem Tab {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'Bleibt diese Option deaktiviert, erreicht ein POS-Verkauf WooCommerce erst bei der nächsten Bestandssynchronisierung — bis zu einer Stunde später.',
'Woo_Settings_Auto_Products_Hint' => 'Ein in Stocky erstelltes, bearbeitetes oder dupliziertes Produkt wird direkt nach dem Speichern an WooCommerce gesendet — Details, Preis, Varianten, Bilder, danach sein Bestand — statt auf eine Produktsynchronisierung zu warten. Massenimporte werden nicht übertragen; führen Sie nach einem Import eine Produktsynchronisierung aus.',
'Woo_Sync_Tuning' => 'Synchronisierungs-Feinabstimmung',
'Woo_Sync_Tuning_Intro' => 'Die Standardwerte passen für die meisten Shops. Ändern Sie diese nur, wenn die Synchronisierung auf Ihrem Hosting langsam ist oder in ein Timeout läuft. Jeder Wert ist auf einen sicheren Bereich begrenzt, und das Leeren eines Felds stellt seinen Standardwert wieder her.',
'Woo_Setting_This_Up' => 'Einrichtung',
'Woo_Setting_This_Up_Text' => 'Wie Sie die API-Schlüssel erhalten, wofür das WordPress-Anwendungspasswort dient, die Cron-Einträge für geplante Synchronisierungen und wie der Bestand den Shop in dem Moment erreicht, in dem er sich ändert — all das, mit den Cron-Zeilen dieses Servers zum Kopieren, finden Sie auf dem Tab „Leitfaden“. Eine einzige Fassung, damit sie nicht von dem abweichen kann, was das Modul tatsächlich tut.',
'Woo_Open_The_Guide' => 'Leitfaden öffnen',
'Woo_Sync_Stock' => 'Bestand synchronisieren',
'Woo_Orders_Stat' => 'WooCommerce-Bestellungen',
'Woo_Imported' => 'Importiert',
