'Telegram_G_A_Title' => 'Sofort — nichts zu installieren',
'Telegram_G_A_Body' => 'Ein in Stocky gespeicherter Verkauf, Einkauf, eine Zahlung oder Ausgabe — am POS oder im Admin-Bereich — wird {after} dem Speichern im selben Request an Telegram gesendet. Kein Cron-Eintrag, kein Queue-Worker, und der Kassierer wartet nie auf Telegram: Der Verkauf wurde bereits beantwortet, wenn die Nachricht hinausgeht.',
'Telegram_G_Right_After' => 'direkt nach',
'Telegram_G_B_Title' => 'Der Cron-Eintrag — für Wiederholungen und Hintergrundereignisse',
'Telegram_G_B_Body' => 'Zwei Arten von Nachrichten warten stattdessen in Telegrams eigener Warteschlange: ein fehlgeschlagener Versand (Telegram kurzzeitig nicht erreichbar), der in den nächsten Minuten bis zu drei weitere Male wiederholt wird, und Ereignisse, die außerhalb der Verwaltung ausgelöst werden — aus WooCommerce oder Shopify importierte Bestellungen, Artisan-Befehle. Dieser Cron-Eintrag versendet sie, und sonst nichts:',
'Telegram_G_Cron_Note' => 'Jede Minute ist richtig: Ein Lauf ohne wartende Nachrichten endet sofort. Unter cPanel gehört dies in {cronJobs} — verwenden Sie den vollständigen Pfad zu PHP 8.2+, falls {php} älter ist. Unter Windows verwenden Sie die Aufgabenplanung mit dem Programm {program}, den Argumenten {args} und dem Startverzeichnis {path}.',
