'Salla_Push_Products_Desc' => 'Erstellt oder aktualisiert einfache Produkte in Salla anhand der SKU. Variantenprodukte werden in dieser Version übersprungen — importieren Sie sie stattdessen aus Salla oder ordnen Sie sie per SKU zu.',
'Salla_Only_Unlinked' => 'Nur noch nicht verknüpfte Produkte',
