'Salla_Pull_Orders_From' => 'Bestellungen aus {name} abrufen',
'Salla_Pull_Orders_Desc' => 'Neue Salla-Bestellungen kommen normalerweise von selbst über Webhooks an und werden zu Verkäufen. Verwenden Sie diesen Abruf, um Bestellungen nachzuholen, die vor der Einrichtung des Webhooks aufgegeben wurden — bereits importierte Bestellungen werden übersprungen.',
'Salla_Import_Into_Warehouse' => 'In Lager importieren',
'Salla_Default_Warehouse_Option' => 'Standard (Einstellungen / erstes Lager)',
'Salla_Pull_Orders' => 'Bestellungen abrufen',
