'Salla_Error' => 'Fehler',
'Salla_Clear_Logs_Confirm' => 'Alle {name}-Protokolle löschen?',
'Salla_Clear_Logs' => 'Protokolle löschen',
'Salla_Guide_1' => 'Erstellen Sie eine (private) App auf {link} und wählen Sie den Autorisierungsablauf {mode}.',
'Salla_Guide_2' => 'Kopieren Sie {clientId} und {clientSecret} der App in den Tab „Verbindung“ und speichern Sie.',
'Salla_Guide_3' => 'Tragen Sie in den Einstellungen der App die OAuth-Callback-URL ein, die auf dem Tab „Verbindung“ angezeigt wird.',
'Salla_Guide_4' => 'Auf der Webhooks-Seite der App: Wählen Sie die Sicherheitsstrategie {signature}, kopieren Sie deren Secret hier in das Feld „Webhook-Secret“, tragen Sie die auf dem Tab „Verbindung“ angezeigte Webhook-URL ein und abonnieren Sie mindestens {e1}, {e2}, {e3}, {e4}, {e5} und {e6}.',
'Salla_Guide_5' => 'Klicken Sie auf {connect} und genehmigen Sie die App in Ihrem Shop. (Apps im Easy Mode verbinden sich stattdessen automatisch über den Webhook {webhook}.)',
'Salla_Guide_6' => 'Rufen Sie Produkte ab oder übertragen Sie sie, und übertragen Sie dann den Bestand. Neue Bestellungen kommen automatisch an und erscheinen unter „Verkäufe“ mit Referenzen wie {ref}.',
'Salla_Identity_Sku_Title' => 'Die Produktidentität ist die SKU',
'Salla_Identity_Sku_Desc' => 'Der Produktcode in Stocky wird mit der SKU in Salla abgeglichen. Halten Sie die SKUs auf beiden Seiten konsistent; Variantenprodukte werden beim Abruf und in Bestellungen zugeordnet, in dieser Version aber nicht übertragen.',
'Salla_Connected_To' => 'Verbunden mit {name}',
