'Salla_Removed_Links' => '{n} Verknüpfungen entfernt',
'Salla_Store_Connected' => 'Salla-Shop verbunden.',
'Presta_Not_Configured' => 'Nicht konfiguriert',
'Presta_Hero_Desc' => 'Synchronisieren Sie Produkte, Bestand und Bestellungen über die Webservice-API mit Ihrem PrestaShop-Shop.',
'Presta_Webservice_Key' => 'Webservice-Schlüssel',
'Presta_Saved_Paste_New_Key' => 'Gespeichert — fügen Sie einen neuen Schlüssel ein, um ihn zu ersetzen',
'Presta_From_Menu' => 'Aus {menu}',
'Presta_Webservice_Key_Help' => 'Aktivieren Sie den Webservice in PrestaShop ({menu}), erstellen Sie einen Schlüssel mit Berechtigungen für products, stock_availables, orders und customers und fügen Sie ihn hier ein. Wird nur schreibend gespeichert.',
'Presta_Shop_Language_Id' => 'Shop-Sprach-ID',
'Presta_Shop_Language_Help' => 'Sprach-ID, die beim Übertragen für Produktnamen verwendet wird (1 = erste Sprache des Shops).',
'Presta_Push_Products_Desc' => 'Legt fehlende einfache Produkte in PrestaShop an (mit ihrem aktuellen Bestand). Bereits verknüpfte Produkte und Variantenprodukte werden übersprungen — bearbeiten Sie Produktdetails weiterhin in PrestaShop oder rufen Sie sie ab, um die lokale Kopie zu aktualisieren.',
'Presta_Pull_Products_Desc' => 'Importiert PrestaShop-Produkte, ordnet vorhandene per Referenz (SKU) zu und legt die übrigen an. Kombinationen werden als ihr übergeordnetes Produkt importiert.',
'Presta_Reset_Product_Confirm' => 'Produktverknüpfungen zurücksetzen? Der Bestellverlauf behält seine Verknüpfungen.',
'Presta_Push_Stock_Desc' => 'Aktualisiert den Bestand des Shops (stock_availables) für jedes verknüpfte Produkt.',
'Presta_Pull_Orders_Desc' => 'Importiert Shop-Bestellungen als Verkäufe (Referenzen wie {ref}), neueste zuerst. Bereits importierte und stornierte Bestellungen werden übersprungen, regelmäßiges Abrufen ist also unbedenklich. PrestaShop hat keine Webhooks — führen Sie dies nach geschäftigen Zeiten aus.',
'Presta_Guide_1' => 'Öffnen Sie in Ihrem PrestaShop-Backoffice {menu} und aktivieren Sie den Webservice.',
'Presta_Guide_2' => 'Fügen Sie einen neuen Schlüssel hinzu und gewähren Sie {rw} auf {products} und {stock} sowie {view} auf {orders} und {customers}.',
'Presta_Guide_3' => 'Fügen Sie die Shop-URL und den Schlüssel auf dem Tab „Verbindung“ ein, speichern Sie und führen Sie {test} aus.',
'Presta_Guide_4' => 'Rufen Sie zuerst Produkte ab, wenn der Shop bereits einen Katalog hat (Zuordnung per Referenz/SKU); übertragen Sie, um fehlende einfache Produkte anzulegen.',
'Presta_Guide_5' => 'Übertragen Sie den Bestand, wann immer sich Mengen ändern, und rufen Sie regelmäßig Bestellungen ab — PrestaShop hat keine Webhooks, Bestellungen kommen also nur beim Abrufen an.',
'Presta_Identity_Title' => 'Die Produktidentität ist die Referenz (SKU)',
'Presta_Identity_Desc' => 'Der Produktcode in Stocky wird mit der Referenz in PrestaShop abgeglichen. Halten Sie die Referenzen auf beiden Seiten konsistent; Kombinationen (Varianten) werden in Bestellungen per Referenz zugeordnet, in dieser Version aber nicht übertragen.',
'Xero_Hero_Title' => 'Xero-Buchhaltungssynchronisierung',
'Xero_Hero_Desc' => 'Übertragen Sie Ihre Kunden als Xero-Kontakte und Ihre Verkäufe als Rechnungen — mit Zahlungen, wenn ein Bankkonto konfiguriert ist.',
'Xero_App_Credentials_Accounts' => 'App-Zugangsdaten & Konten',
'Xero_From_Dev_App' => 'Aus Ihrer App auf developer.xero.com',
