'Xero_Payment_Account_Code' => 'Zahlungskontonummer (optional)',
'Xero_Payment_Account_Ph' => 'z. B. 090',
'Xero_Payment_Account_Help' => 'Eine Bankkontonummer. Wenn gesetzt, erfassen bezahlte Verkäufe auch eine Zahlung auf der Rechnung; leer lassen, um nur Rechnungen zu synchronisieren.',
'Xero_Auto_Sync_Sales' => 'Neue Verkäufe automatisch als Rechnungen synchronisieren',
'Xero_Auto_Sync_Sales_Hint' => '(wird beim Anlegen von Verkäufen im Hintergrund in die Warteschlange gestellt)',
