'Xero_Disconnect_Confirm' => 'Xero-Organisation trennen? Die Synchronisierung stoppt, bis Sie die Verbindung wiederherstellen.',
'Xero_Redirect_Uri_Title' => 'Redirect-URI für die Xero-App',
'Xero_Redirect_Uri_Help' => 'Erstellen Sie eine "Web app" auf {link} und registrieren Sie diese Redirect-URI. Hinweis: Xero-Zugriffstoken werden automatisch erneuert, aber eine Verbindung, die über 60 Tage ungenutzt ist, muss neu verbunden werden.',
'Xero_Total_Customers' => 'Kunden gesamt',
'Xero_Contacts_In_Xero' => 'Kontakte in Xero',
'Xero_Total_Sales' => 'Verkäufe gesamt',
'Xero_Invoices_In_Xero' => 'Rechnungen in Xero',
'Xero_Payments_Recorded' => 'Erfasste Zahlungen',
'Xero_Push_Customers_To' => 'Kunden an {name} übertragen',
'Xero_Push_Customers_Desc' => 'Erstellt oder aktualisiert für jeden Kunden einen Xero-Kontakt. Ein Kunde, dessen Name in Xero bereits existiert, wird mit diesem Kontakt verknüpft.',
'Xero_Push_Customers' => 'Kunden übertragen',
'Xero_Push_Sales_Invoices' => 'Verkäufe als Rechnungen übertragen',
'Xero_Push_Invoices_Desc' => 'Erstellt pro Verkauf eine AUTHORISED-Rechnung (Rechnungsnummer = Referenz des Verkaufs) mit den Positionen des Verkaufs plus Versand-, Rabatt- und Steuerzeilen, sodass der Xero-Gesamtbetrag dem Verkaufsgesamtbetrag entspricht. Bereits in Xero vorhandene Verkäufe werden übersprungen — Rechnungen werden nie bearbeitet. Fehlende Kontakte werden bei Bedarf angelegt.',
'Xero_Push_Invoices' => 'Rechnungen übertragen',
'Xero_Reset_Contact_Confirm' => 'Kontaktverknüpfungen zurücksetzen? Die nächste Übertragung verknüpft sie neu oder legt sie neu an.',
'Xero_Reset_Contact_Links' => 'Kontaktverknüpfungen zurücksetzen',
'Xero_Guide_1' => 'Erstellen Sie eine {webApp} auf {link} ({menu}).',
'Xero_Guide_2' => 'Registrieren Sie die Redirect-URI, die auf dem Tab „Verbindung“ angezeigt wird.',
'Xero_Guide_3' => 'Kopieren Sie die {clientId} der App und erzeugen Sie ein {clientSecret}; fügen Sie beide hier ein und speichern Sie.',
'Xero_Guide_4' => 'Klicken Sie auf {connect}, melden Sie sich an und wählen Sie die zu verbindende Organisation.',
'Xero_Guide_5' => 'Prüfen Sie die Kontonummern: Das Erlöskonto erhält die Rechnungspositionen; geben Sie eine Bankkontonummer an, wenn bezahlte Verkäufe auch Zahlungen erfassen sollen.',
'Xero_Guide_6' => 'Übertragen Sie zuerst Kunden, dann Rechnungen. Die Rechnungsnummern sind die Referenzen der Verkäufe, daher lehnt Xero Duplikate ab, selbst wenn Verknüpfungen zurückgesetzt werden.',
'Xero_Amounts_Title' => 'Beträge werden unverändert inklusive Steuer übertragen',
'Xero_Amounts_Desc' => 'Rechnungen verwenden NoTax-Zeilen, die den Verkauf exakt abbilden (Artikel + Versand − Rabatt + Steuer), sodass die Xero-Summen immer den Stocky-Summen entsprechen. Ihr Buchhalter kann die Steuer- und Versandzeilen in Xero den passenden Konten zuordnen.',
'Xero_Org_Connected' => 'Xero-Organisation verbunden.',
'Jumia_Hero_Title' => 'Jumia-Marktplatz-Synchronisierung',
'Jumia_Hero_Desc' => 'Übertragen Sie Preise und Bestand an Ihre Jumia-Seller-Center-Angebote und importieren Sie Marktplatz-Bestellungen als Verkäufe.',
'Jumia_Api_Url_Label' => 'API-URL (der Seller-Center-Endpunkt Ihres Landes)',
'Jumia_Account_Email' => 'Konto-E-Mail (User ID)',
'Jumia_Api_Key' => 'API-Schlüssel',
'Jumia_Prices_Stock' => 'Preise & Bestand',
'Jumia_Push_Prices_Stock_Title' => 'Preise & Bestand an Jumia übertragen',
'Jumia_Push_Prices_Stock_Desc' => 'Sendet den aktuellen Preis und die Menge für jedes Produkt (und jede Variante), dessen SKU der {sku} des Jumia-Angebots entspricht. Aktualisierungen werden als Seller-Center-Feeds übermittelt und asynchron angewendet — die Feed-ID wird im Tab „Protokolle“ erfasst, und Ablehnungen einzelner Artikel erscheinen in der Feed-Status-Ansicht des Seller Centers.',
'Jumia_Push_Prices_Stock' => 'Preise & Bestand übertragen',
'Jumia_Pull_Orders_Desc' => 'Importiert Marktplatz-Bestellungen als Verkäufe (Referenzen wie {ref}), zugeordnet zu Ihren Produkten per Seller SKU. Bereits importierte und stornierte Bestellungen werden übersprungen, regelmäßiges Abrufen ist also unbedenklich. Zahlungen werden nur bei zugestellten Bestellungen als bezahlt markiert (bei Jumia überwiegt Nachnahme).',
'Jumia_Guide_1' => 'Öffnen Sie im Jumia {sellerCenter} den Bereich {menu} und erzeugen Sie einen API-Schlüssel.',
'Jumia_Guide_2' => 'Geben Sie die API-URL Ihres Landes (z. B. {ng} für Nigeria, {ke} für Kenia, {eg} für Ägypten), die E-Mail Ihres Seller-Center-Kontos und den Schlüssel ein — führen Sie dann {test} aus.',
'Jumia_Guide_3' => 'Stellen Sie sicher, dass die {sku} jedes Jumia-Angebots dem Stocky-Produktcode entspricht — das ist die Identität, die sowohl für Bestandsübertragungen als auch für die Bestellzuordnung verwendet wird.',
'Jumia_Guide_4' => 'Übertragen Sie Preise & Bestand nach Bestandsänderungen; rufen Sie regelmäßig Bestellungen ab (Jumia hat in dieser API keine Webhooks).',
'Jumia_Guide_5' => 'Neue Angebote werden weiterhin im Seller Center erstellt — Jumia verlangt kategoriespezifische Attribute und eine Bildprüfung, die nur das eigene Portal zuverlässig abwickelt.',
'Mailchimp_Hero_Title' => 'Mailchimp-Zielgruppen-Synchronisierung',
'Mailchimp_Hero_Desc' => 'Füllen Sie eine Mailchimp-Zielgruppe mit Ihren Kunden, damit Sie E-Mail-Kampagnen mit Ihrem echten Kundenstamm durchführen können.',
'Mailchimp_Account_Audience' => 'Konto & Zielgruppe',
'Mailchimp_Api_Key_Ph' => 'z. B. {example} ({menu})',
'Mailchimp_Audience_Option' => '{name} ({n} Mitglieder)',
'Mailchimp_Load_Audiences_Ph' => 'Zielgruppen laden, um eine auszuwählen',
'Mailchimp_Load_Audiences' => 'Zielgruppen laden',
'Mailchimp_Double_Optin_Label' => 'Double-Opt-in — neue Mitglieder erhalten vor der Aufnahme eine Bestätigungs-E-Mail',
'Mailchimp_Double_Optin_Hint' => '(empfohlen für die DSGVO)',
'Mailchimp_Auto_Sync_Customers' => 'Neue Kunden beim Anlegen automatisch synchronisieren',
'Mailchimp_With_Email' => 'Mit E-Mail',
'Mailchimp_Push_Desc' => 'Fügt jeden Kunden mit E-Mail-Adresse in die ausgewählte Zielgruppe ein oder aktualisiert ihn (inklusive Name und Telefon). Bestehende Mitglieder behalten ihren Abonnementstatus — niemand, der sich abgemeldet hat, wird erneut angemeldet. Kunden ohne E-Mail werden ausgelassen.',
'Mailchimp_Double_Optin_Off_Title' => 'Double-Opt-in ist ausgeschaltet',
'Mailchimp_Double_Optin_Off_Desc' => 'Neue Mitglieder werden ohne Bestätigungs-E-Mail als angemeldet hinzugefügt. Tun Sie dies nur für Kunden, die dem Erhalt von Marketing bereits zugestimmt haben.',
'Mailchimp_Guide_1' => 'Öffnen Sie in Mailchimp {menu} und erstellen Sie einen Schlüssel (er endet auf {suffix} — dieses Suffix ist Ihr Rechenzentrum).',
'Mailchimp_Guide_2' => 'Fügen Sie den Schlüssel hier ein, speichern Sie, klicken Sie dann auf {load} und wählen Sie die zu befüllende Zielgruppe.',
'Mailchimp_Guide_3' => 'Lassen Sie {doubleOptIn} eingeschaltet, es sei denn, Ihre Kunden haben Marketing-E-Mails bereits zugestimmt.',
'Mailchimp_Double_Optin_Term' => 'Double-Opt-in',
'Mailchimp_Guide_4' => 'Führen Sie {push} für die Erstbefüllung aus; schalten Sie {autoSync} ein, damit neue Kunden automatisch hinzugefügt werden.',
'Mailchimp_Auto_Sync_Term' => 'automatische Synchronisierung',
'Mailchimp_Consent_Title' => 'Einwilligung ist wichtig',
'Mailchimp_Consent_Desc' => 'E-Mails an Personen, die Marketing nie zugestimmt haben, können gegen DSGVO/CAN-SPAM verstoßen und zur Sperrung Ihres Mailchimp-Kontos führen. Double-Opt-in verlagert die Bestätigung zu Mailchimp — die sichere Voreinstellung.',
'Mailchimp_No_Audiences' => 'Für dieses Konto wurden keine Zielgruppen gefunden.',
