'GSheets_Guide_2' => 'Konfigurieren Sie den {consent} (External). Solange er im Status "Testing" bleibt, fügen Sie Ihr Google-Konto als Testnutzer hinzu — beachten Sie, dass Refresh-Tokens im Testmodus nach 7 Tagen ablaufen; {publish} Sie die App daher für eine dauerhafte Verbindung.',
'GSheets_Publish' => 'veröffentlichen',
