'Shopify_G_Lead_Generic' => 'Wie ein Shopify-Shop mit dem ERP synchron bleibt. Wählen Sie oben einen Shop, um seinen eigenen Status zu sehen, oder lesen Sie die Anleitung so, wie sie ist — die Cron-Zeile und die Webhook-URL sind für jeden verbundenen Shop dieselben.',
'Shopify_G_Ways_Note' => 'Die meisten Shops nutzen beides: Der erste Weg hält den Shop minütlich aktuell, der zweite fängt alles auf, was der erste verpasst hat — einen Webhook, der nie ankam, eine direkt im Shopify-Admin vorgenommene Änderung, eine Nacht, in der die Website nicht erreichbar war.',
