'Shopify_G_Credentials' => 'Shopify-Zugangsdaten',
'Shopify_G_Cred_Intro' => 'Seit Januar 2026 erstellt Shopify keine benutzerdefinierten Apps mehr im Admin-Bereich, daher gibt es zwei Arten von Verbindungen:',
'Shopify_G_Cred_DevDash' => '{app} (jeder jetzt verbundene Shop) — {path}. Gewähren Sie die Admin-API-Scopes für das, was dieser Shop synchronisiert, installieren Sie die App im Shop und kopieren Sie dann {clientId} und {clientSecret} von der Einstellungsseite der App nach {where}. Das ERP tauscht diese selbst gegen ein Zugriffstoken ein und erneuert es, bevor es nach jeweils 24 Stunden abläuft. Das Client Secret signiert auch die Webhooks, sodass nichts weiter benötigt wird. App und Shop müssen sich in derselben Shopify-Organisation befinden.',
'Shopify_G_Dev_Dashboard_App' => 'Dev-Dashboard-App',
'Shopify_G_Cred_Legacy' => '{app} (vor 2026 im Admin-Bereich erstellt) — funktioniert unverändert weiter mit ihrem {token} ({prefix}) und ihrem {secret} als Webhook-Signaturschlüssel. Dieser Wert ist nicht identisch mit dem Token, und eine Verwechslung der beiden ist der häufigste Grund, warum Webhooks abgelehnt werden.',
'Shopify_G_Legacy_App' => 'Ältere benutzerdefinierte App',
'Shopify_G_API_Secret_Key' => 'API-Geheimschlüssel',
'Shopify_G_Stored' => 'gespeichert',
'Shopify_G_Missing_Refused' => 'fehlt — Zustellungen werden abgelehnt',
'Shopify_G_Where_Data_Desc' => '{path} Das ERP-Lager, dessen Bestand dieser Shop verkauft, und der Shopify-Standort, an den dieser Bestand geschrieben wird. Bestandssynchronisierung und Bestellimport werden ohne diese Angaben nicht ausgeführt.',
'Shopify_G_Currently' => 'Aktuell: Lager {warehouse}, Standort {location}',
'Shopify_G_Not_Set_Lower' => 'nicht festgelegt',
'Shopify_G_Ready' => 'bereit',
'Shopify_G_Incomplete' => 'unvollständig',
'Shopify_G_Manual_Syncs' => 'Manuell gestartete Synchronisierungen',
'Shopify_G_Manual_Desc' => 'Eine im {centre} gestartete Synchronisierung antwortet sofort und läuft im Hintergrund in kurzen Abschnitten, die jeweils dort weitermachen, wo der letzte aufgehört hat. Ein großer Katalog wird so nie mittendrin von einem Hosting abgebrochen, das lange Web-Anfragen beendet (LiteSpeed, nginx, ein Load Balancer), und das Schließen der Seite stoppt ihn nicht. Der Worker dafür ist eine weitere Cron-Zeile:',
'Shopify_G_Cron_Copied' => 'Cron-Zeile kopiert',
'Shopify_G_Manual_Note' => 'Ohne sie wird eine Synchronisierung trotzdem abgeschlossen, aber nur, solange die Seite des Sync Centre geöffnet bleibt: Übernimmt innerhalb weniger Sekunden kein Worker einen Lauf, führt die Seite ihn selbst fort, eine kurze Anfrage nach der anderen. Unter Windows verwenden Sie die Aufgabenplanung jede Minute: Programm {program}, Argumente {args}, gestartet in {dir}.',
'Shopify_G_Then_Pick' => 'Wählen Sie dann, wie die Synchronisierung erfolgt',
'Shopify_G_Right_Away' => 'Sofort',
'Shopify_G_Stock_Live' => 'Bestand live',
'Shopify_G_Stock_Not_Live' => 'Bestand nicht live',
'Shopify_G_Realtime_Lead' => 'Jede Änderung wird sofort, innerhalb von Sekunden, übertragen. Zwei Hälften mit getrennten Schaltern: {webhooks} holen die Ereignisse des Shops herein, und {push} sendet den Bestand hinaus.',
'Shopify_G_Webhooks_Lower' => 'Webhooks',
'Shopify_G_Instant_Push_Lower' => 'Sofortige Bestandsübertragung',
'Shopify_G_Webhooks_In' => 'Webhooks — Shop → ERP',
'Shopify_G_Webhooks_Desc' => 'Bestellungen, Statusänderungen von Bestellungen sowie in Shopify vorgenommene Änderungen an Produkten, Kunden und Bestand. Öffnen Sie den Shop und klicken Sie auf {button} im {tab} — zweimal Klicken ist unbedenklich. Shopify sendet an:',
'Shopify_G_Webhooks_Tab' => 'Tab „Webhooks“',
'Shopify_G_Webhooks_Note' => 'Die Adresse muss aus dem Internet über HTTPS erreichbar sein — Shopify liefert nicht an {localhost} oder eine {test}-Domain. Jede Zustellung wird nur einmal erfasst, sodass Wiederholungsversuche von Shopify keine doppelte Bestellung erzeugen können, und eine fehlgeschlagene Zustellung kann erneut verarbeitet werden. Zustellungen werden abgelehnt, bis der Signaturschlüssel aus Schritt 1 gespeichert ist.',
'Shopify_G_Instant_Out' => 'Sofortige Bestandsübertragung — ERP → Shop',
'Shopify_G_Setting_Missed' => 'Diese Einstellung wird häufig übersehen',
'Shopify_G_Pos_Not_Auto' => 'Ein POS-Verkauf gelangt {not} von selbst zu Shopify. Bleibt die Option deaktiviert, erfährt der Shop erst beim nächsten Schritt der Bestandsübertragung davon — und in diesem Zeitraum kann er eine Einheit verkaufen, die Sie bereits an der Kasse verkauft haben.',
'Shopify_G_Not' => 'nicht',
'Shopify_G_Tick_Push' => 'Aktivieren Sie {setting} unter {where}. Das ist die gesamte Einrichtung — kein Worker, kein Cron. Jeder Verkauf, jede Retoure und jede Bestandskorrektur sendet dann direkt nach dem Speichern eine Übertragung nur der betroffenen Produkte, und ein Verkauf mit zwanzig Positionen kostet eine Übertragung, nicht zwanzig. Die Kasse wartet nie darauf.',
'Shopify_G_This_Store' => 'Dieser Shop:',
'Shopify_G_Push_On' => 'an — Bestand wird bei Änderung übertragen',
'Shopify_G_Push_Off' => 'aus — Bestand nur nach Zeitplan',
'Shopify_G_Push_Note' => 'Übertragen werden nur Produkte, die bereits eine Shopify-Zuordnung haben, und nur Bewegungen im Lager dieses Shops. Massenoperationen — das Löschen eines Produkts, das Zurücksetzen eines Lagers — schreiben den Bestand, ohne ein Ereignis auszulösen; ein Grund, den geplanten Bestandsschritt ebenfalls beizubehalten.',
'Shopify_G_Nothing_Install' => 'Sonst muss nichts installiert werden',
'Shopify_G_No_Worker_Note' => 'Keine der beiden Hälften benötigt einen Queue-Worker oder einen Cron-Eintrag. Ein eingehender Webhook wird in der Anfrage verarbeitet, die Shopify stellt; eine ausgehende Bestandsübertragung läuft im selben Prozess, der den Verkauf bearbeitet hat, {after} die Antwort zurückgesendet wurde — so wartet die Kasse nie auf Shopify, und ein Shop, der nicht mehr antwortet, wird nach zehn Sekunden aufgegeben und der nächsten geplanten Bestandsübertragung überlassen.',
'Shopify_G_After' => 'nachdem',
'Shopify_G_Artisan_Note' => 'Eine Ausnahme: Eine durch einen Artisan-Befehl ausgelöste Bestandsänderung hat keine Antwort, nach der sie laufen könnte, daher wird sie stattdessen in die Queue {queue} gestellt. Wenn diese ebenfalls zeitnah übertragen werden sollen, arbeiten Sie diese Queue ab:',
'Shopify_G_On_Schedule' => 'Nach Zeitplan',
'Shopify_G_On_Lower' => 'an',
'Shopify_G_Off_Lower' => 'aus',
'Shopify_G_Scheduled_Lead' => 'Alles wird regelmäßig in beide Richtungen erneut geprüft. Langsamer als in Echtzeit, aber so wird der Bestand bei Shops ohne sofortige Übertragung hinausgesendet, ein verpasster Webhook aufgefangen, und es ist die einzige Möglichkeit, einen ganzen Katalog zu übertragen.',
'Shopify_G_Cron_Entry' => 'Der Cron-Eintrag',
'Shopify_G_Cron_Entry_Desc' => 'Ohne ihn läuft nichts Geplantes. Eine Zeile, nur für dieses Modul — fügen Sie sie neben allem anderen ein, das Sie zeitgesteuert ausführen:',
'Shopify_G_Cron_Note' => 'Alle fünf Minuten ist die feinste Auflösung, die ein Plan nutzen kann, da fünf Minuten das kürzeste Schrittintervall sind. Ein gröberer Eintrag wird einfach zur Untergrenze — mit {example} läuft ein auf 5 Minuten eingestellter Schritt alle 15 Minuten. Unter Windows verwenden Sie die Aufgabenplanung: Programm {program}, Argumente {args}, gestartet in {dir}.',
'Shopify_G_Switch_On_Plan' => 'Aktivieren und Plan wählen',
'Shopify_G_Plan_Desc' => '{where} Der Schalter entscheidet, ob Cron überhaupt aktiv werden darf; der Plan entscheidet, was er tut. Ein {step} ist eine Entität in einer Richtung mit eigenem Intervall — {first}, {second}. Das Standardintervall gilt für jeden Schritt, dessen eigenes Feld leer bleibt.',
'Shopify_G_Step_Lower' => 'Schritt',
'Shopify_G_Plan_Note' => 'Bleibt der Plan leer, holt der Shop Bestellungen ab und überträgt den Bestand im Standardintervall, was die meisten Shops wünschen. Bestellungen werden nur abgeholt: Shopify ist der Ort, an dem ein Kunde sie aufgibt.',
'Shopify_G_Schedule_On' => 'Zeitplan an',
'Shopify_G_Schedule_Off' => 'Zeitplan aus — nur manuell',
'Shopify_G_When_Step_Runs' => 'Wann ein Schritt tatsächlich ausgeführt wird',
'Shopify_G_When_Note' => 'Ein Schritt ist fällig, wenn derselbe Schritt zuletzt vor längerer Zeit als sein Intervall {started} wurde, ermittelt aus dem Ausführungsverlauf. Eine manuell gestartete Synchronisierung verschiebt also die nächste automatische, und ein Schritt, der wiederholt fehlschlägt, wird in seinem Intervall erneut versucht statt bei jedem Takt. Die Übersicht des Shops zeigt für jeden Schritt die letzte Ausführung, die nächste Fälligkeit und gegebenenfalls den Grund für eine Blockierung. Führen Sie die erste Katalogübertragung manuell aus — zuerst mit {dryRun} —, bevor Sie sie in einen Zeitplan aufnehmen.',
'Shopify_G_Started_Lower' => 'gestartet',
'Shopify_G_Where_Setting' => 'Wo sich die einzelnen Einstellungen befinden',
'Shopify_G_Where_Setting_Note' => 'Alle befinden sich bei einem bestehenden Shop: {path}, dann der Stift (oder {edit} auf der eigenen Seite des Shops).',
'Shopify_G_Product_Images' => 'Produktbilder',
'Shopify_G_Img_1' => 'Bilder werden bei einer {push} mit dem Produkt übertragen — zuerst das Hauptbild, dann die Galerie, dann eines pro Variante mit eigenem Bild, bis zu fünfzig.',
'Shopify_G_Products_Push' => 'Produktübertragung',
'Shopify_G_Img_2' => 'Das Bild einer Variante wird mit dem Produkt hochgeladen und dann {assigned}, so wie Shopify es abbildet: Eine Variante verweist auf eines der Bilder des Produkts. Eine Variante, die das Hauptbild wiederverwendet, lädt es nicht doppelt hoch.',
'Shopify_G_Assigned' => 'dieser Variante zugewiesen',
'Shopify_G_Img_3' => 'Ein als Datei gespeichertes Bild wird zu Shopify {uploaded}, nicht verlinkt, sodass es auch funktioniert, wenn diese Installation nicht aus dem Internet erreichbar ist. Ein als eingefügter Link hinzugefügtes Bild wird Shopify als diese URL übergeben, die öffentlich erreichbar sein muss.',
'Shopify_G_Uploaded' => 'hochgeladen',
'Shopify_G_Img_4' => 'Sie werden nur erneut gesendet, wenn sie sich tatsächlich ändern — eine Übertragung, die nur einen Preis ändert, lässt die Bilder des Shops unberührt, da das Senden den gesamten Bildsatz ersetzt.',
'Shopify_G_Img_5' => 'Das Entfernen eines Bildes im ERP löscht es in Shopify {not}. Löschen Sie es auch dort, sonst zeigt der Shop es weiterhin an.',
'Shopify_G_Commands' => 'Wissenswerte Befehle',
'Shopify_G_Command_Copied' => 'Befehl kopiert',
'Shopify_G_Foot' => 'Jede Synchronisierung schreibt in {logs}, und die Übersicht jedes Shops zeigt, wann jeder Schritt zuletzt lief, wann er als Nächstes fällig ist und was ihn gegebenenfalls blockiert. Dort sollten Sie zuerst nachsehen, wenn eine Synchronisierung nicht das getan hat, was Sie erwartet haben.',
'Shopify_G_Covers' => 'Umfasst',
'Shopify_G_Covers_Rt' => 'Bestellungen und Änderungen in Shopify; Bestand, der das ERP verlässt (ein POS-Verkauf, eine Retoure, eine Bestandskorrektur)',
'Shopify_G_Covers_Sch' => 'Alles, in beide Richtungen — einschließlich Katalogübertragungen und allem, was der schnelle Weg verpasst hat',
'Shopify_G_Speed' => 'Geschwindigkeit',
'Shopify_G_Speed_Rt' => 'Sekunden',
'Shopify_G_Speed_Sch' => 'Das Intervall des Schritts (5 Minuten bis 7 Tage)',
'Shopify_G_Needs' => 'Benötigt',
'Shopify_G_Needs_Rt' => 'Eine öffentliche HTTPS-Adresse und den Signaturschlüssel für eingehende Webhooks. Ausgehender Bestand benötigt überhaupt nichts',
'Shopify_G_Needs_Sch' => 'Einen Cron-Eintrag, der {cmd} ausführt',
'Shopify_G_Switched_On_At' => 'Aktiviert unter',
'Shopify_G_On_Sch' => '{path}, plus der Plan',
'Shopify_G_Scope_Orders' => '{scope} ({extra} für Bestellungen, die älter als 60 Tage sind)',
'Shopify_G_Admin_Scopes' => 'Admin-API-Scopes',
'Shopify_G_Setting' => 'Einstellung',
'Shopify_G_Tab_In_Edit' => 'Tab in „Shop bearbeiten“',
'Shopify_G_Set_Credentials' => 'Client-ID + Secret oder Zugriffstoken, Signaturschlüssel, API-Version',
'Shopify_G_Set_Credentials_What' => 'Die Zugangsdaten aus der Shopify-App (Dev Dashboard oder ältere benutzerdefinierte App).',
'Shopify_G_Set_Targets' => 'ERP-Lager, Shopify-Standort',
'Shopify_G_Set_Targets_What' => 'Welchen Bestand dieser Shop verkauft und wo Bestellungen abgelegt werden.',
'Shopify_G_Set_Price_What' => 'Einzelhandels-, Großhandels- oder Mindestpreis.',
'Shopify_G_Set_Create_Missing' => 'Fehlende Produkte / Kunden erstellen',
'Shopify_G_Set_Create_Missing_What' => 'Ob ein Abruf ERP-Datensätze erstellen darf, die er nicht zuordnen kann.',
'Shopify_G_Set_Entities' => 'Welche Entitäten überhaupt synchronisiert werden',
'Shopify_G_Set_Entities_What' => 'Hier aus bedeutet überall aus — manuell, geplant und per Webhook.',
'Shopify_G_Set_Scheduler_What' => 'Der Schalter für den Zeitplaner.',
'Shopify_G_Set_Push_What' => 'Sofortige Bestandsübertragung, ausgelöst durch einen Verkauf oder eine Bestandskorrektur.',
'Shopify_G_Set_Plan' => 'Standardintervall und der Schrittplan',
'Shopify_G_Set_Plan_What' => 'Was automatisch läuft, in welche Richtung und wie oft.',
'Shopify_G_Cmd_List' => 'Alle Shops: was laufen würde und wann. Ändert nichts.',
'Shopify_G_Cmd_Force' => 'Den gesamten Plan eines Shops jetzt ausführen, unabhängig vom Zeitpunkt.',
'Shopify_G_Cmd_First_Push' => 'Erste Katalogübertragung: nur noch nicht verknüpfte Produkte.',
'Shopify_G_Cmd_Backfill' => 'Bestellungen ab einem Datum nachträglich importieren.',
'Shopify_G_Cmd_Dry' => 'Durchlaufen und berichten, ohne irgendwo etwas zu schreiben.',
