'StoreAdm_Banner_Center_Left' => 'Mitte — Links',
'StoreAdm_Banner_Center_Right' => 'Mitte — Rechts',
'StoreAdm_Banner_Footer_Left' => 'Fußzeile — Links',
'StoreAdm_Banner_Footer_Right' => 'Fußzeile — Rechts',
'StoreAdm_NA' => 'k. A.',
'StoreAdm_Eg' => 'z. B. {example}',
'StoreAdm_Stock_Required_Available' => '{name}: Benötigt {need} — Verfügbar {have}',
'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash und SSLCommerz werden nur vom Checkout des ONLINE-SHOPS verwendet.',
'StoreAdm_PG_Intro_Desc' => 'Stripe-Schlüssel werden global gemeinsam genutzt (Admin-Bereich und Online-Shop verwenden dieselbe Stripe-Integration). Jeder Tab aktiviert oder deaktiviert seine Zahlungsmethode für den Online-Shop-Checkout; „Offline-Zahlungen“ enthält die Methoden, die außerhalb des Systems bezahlt werden.',
'StoreAdm_PG_Used_By_Store_Only' => 'Wird nur vom Online-Shop-Checkout verwendet',
'StoreAdm_PG_Gw_Key' => '{gw}-Schlüssel',
'StoreAdm_PG_Gw_Secret' => '{gw}-Secret',
'StoreAdm_PG_Cards_Off' => 'Kartenzahlungen sind deaktiviert',
'StoreAdm_PG_Cards_Off_Desc' => 'Ihre Schlüssel bleiben erhalten — der Online-Shop-Checkout bietet die Kartenoption lediglich nicht mehr an, bis Sie sie wieder aktivieren.',
'StoreAdm_PG_No_Stripe_Key' => 'Kein Stripe-Schlüssel gespeichert',
'StoreAdm_PG_No_Stripe_Key_Desc' => 'Geben Sie Ihren Stripe-Schlüssel und Ihr Secret ein, um im Online-Shop Kartenzahlungen zu akzeptieren.',
'StoreAdm_PG_Gw_Client_Id' => '{gw} Client-ID',
'StoreAdm_PG_Gw_Client_Secret' => '{gw} Client Secret',
'StoreAdm_PG_Sandbox' => 'Sandbox (Testmodus)',
'StoreAdm_PG_Sandbox_Paypal_Hint' => 'AN verwendet {sandbox} mit Sandbox-Zugangsdaten; schalten Sie AUS, um echte Konten über {live} zu belasten.',
'StoreAdm_PG_Gw_Webhook_Id_Opt' => '{gw} Webhook-ID (optional)',
'StoreAdm_PG_Paypal_Webhook_Hint' => 'Absicherung für Zahlungen, deren Browser-Weiterleitung nie ankommt, sowie für Erstattungen/Rückbuchungen. Registrieren Sie auf {site} einen Webhook, der auf die untenstehende URL verweist (Ereignisse: {events}), und fügen Sie hier seine Webhook-ID ein.',
'StoreAdm_PG_Webhook_Url' => 'Webhook-URL:',
'StoreAdm_PG_Gw_Disabled' => '{gw} ist deaktiviert',
'StoreAdm_PG_Paypal_Disabled_Desc' => 'Aktivieren Sie PayPal und geben Sie die Client-ID und das Secret Ihrer REST-App (von {site}) ein, damit Kunden im Online-Shop-Checkout mit PayPal bezahlen können.',
'StoreAdm_PG_Gw_Public_Key' => '{gw} Public Key',
'StoreAdm_PG_Gw_Secret_Key' => '{gw} Secret Key',
'StoreAdm_PG_Paystack_Test_Live' => 'Test- oder Live-Modus wird durch das Schlüsselpaar bestimmt: {test}-Schlüssel laufen im Testmodus, {live}-Schlüssel belasten echte Karten — es gibt keinen separaten Sandbox-Schalter.',
'StoreAdm_PG_Paystack_Webhook_Url' => 'Webhook-URL (optionale Absicherung — festzulegen unter Settings → API Keys & Webhooks im Paystack-Dashboard; Anfragen werden per HMAC mit Ihrem Secret Key verifiziert):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'Aktivieren Sie Paystack und geben Sie Ihren Public und Secret Key (von {site} → Settings → API Keys) ein, um im Online-Shop-Checkout Karten, Banküberweisungen und Mobile Money zu akzeptieren.',
'StoreAdm_PG_Secret_Hash_Opt' => 'Secret Hash (Webhooks, optional)',
'StoreAdm_PG_Flutterwave_Hash_Hint' => 'Der Secret Hash, den Sie unter Settings → Webhooks im Flutterwave-Dashboard festgelegt haben; eingehende Webhooks werden abgelehnt, wenn ihr {header}-Header nicht übereinstimmt.',
'StoreAdm_PG_Flutterwave_Info' => 'Verwendet die Flutterwave-v3-API mit klassischen Schlüsseln. Test- oder Live-Modus wird durch das Schlüsselpaar bestimmt ({keys} vs. Live-Schlüssel) — es gibt keinen separaten Sandbox-Schalter. Die Shop-Währung muss in Ihrem Flutterwave-Konto aktiviert sein.',
'StoreAdm_PG_Flutterwave_Webhook_Url' => 'Webhook-URL (optionale Absicherung — zusammen mit dem obigen Secret Hash im Flutterwave-Dashboard festlegen):',
'StoreAdm_PG_Flutterwave_Disabled_Desc' => 'Aktivieren Sie Flutterwave und geben Sie Ihren v3 Public und Secret Key (von {site} → Settings → API) ein, um im Online-Shop-Checkout Karten, Mobile Money und Banküberweisungen zu akzeptieren.',
'StoreAdm_PG_Gw_Key_Id' => '{gw} Key-ID',
'StoreAdm_PG_Gw_Key_Secret' => '{gw} Key Secret',
'StoreAdm_PG_Webhook_Secret_Opt' => 'Webhook-Secret (optional)',
'StoreAdm_PG_Razorpay_Secret_Hint' => 'Das Secret, das Sie beim Erstellen des Webhooks im Razorpay-Dashboard festlegen; eingehende Ereignisse werden per HMAC damit verifiziert und andernfalls abgelehnt.',
'StoreAdm_PG_Razorpay_Info' => 'Verwendet Razorpay Payment Links (Karten, UPI, Netbanking, Wallets). Test- oder Live-Modus wird durch das Schlüsselpaar bestimmt ({keys}) — es gibt keinen separaten Sandbox-Schalter.',
'StoreAdm_PG_Razorpay_Webhook_Url' => 'Webhook-URL (optionale Absicherung — mit dem obigen Secret unter Settings → Webhooks registrieren; Ereignisse: {events}):',
'StoreAdm_PG_Razorpay_Disabled_Desc' => 'Aktivieren Sie Razorpay und geben Sie Ihre Key-ID und Ihr Key Secret (von {site} → Settings → API Keys) ein, um im Online-Shop-Checkout Karten, UPI, Netbanking und Wallets zu akzeptieren.',
'StoreAdm_PG_Gw_App_Key' => '{gw} App Key',
'StoreAdm_PG_Gw_App_Secret' => '{gw} App Secret',
'StoreAdm_PG_Gw_Username' => '{gw} Benutzername',
'StoreAdm_PG_Gw_Password' => '{gw} Passwort',
'StoreAdm_PG_Sandbox_Bkash_Hint' => 'AN verwendet {sandbox} mit Ihren Sandbox-Zugangsdaten; schalten Sie AUS, um echte bKash-Konten über {live} zu belasten.',
'StoreAdm_PG_Bkash_Info' => 'Verwendet bKash Tokenized Checkout (Händler-Zugangsdaten aus dem bKash-Händlerportal). bKash rechnet nur in BDT ab — die Option wird im Checkout nur angeboten, solange die aktive Währung des Shops BDT ist.',
'StoreAdm_PG_Bkash_Disabled_Desc' => 'Aktivieren Sie bKash und geben Sie App Key, App Secret, Benutzername und Passwort Ihres Tokenized Checkout (aus dem bKash-Händlerportal) ein, damit Kunden im Online-Shop-Checkout mit bKash bezahlen können.',
'StoreAdm_PG_Gw_Store_Id' => '{gw} Store-ID',
'StoreAdm_PG_Gw_Store_Password' => '{gw} Store-Passwort',
'StoreAdm_PG_Sandbox_Sslcommerz_Hint' => 'AN verwendet {sandbox} mit Sandbox-Zugangsdaten; schalten Sie AUS, um echte Kunden über {live} zu belasten.',
'StoreAdm_PG_Sslcommerz_Info' => 'Gehosteter Checkout für Karten, bKash/Nagad/Rocket Mobile Banking und Internetbanking in Bangladesch. Die Zugangsdaten stammen aus Ihrem SSLCommerz-Händlerbereich (Store-ID + Store-Passwort / API-Zugangsdaten).',
'StoreAdm_PG_Sslcommerz_Ipn_Url' => 'IPN-URL (empfohlene Absicherung — festzulegen unter My Stores → IPN Settings im SSLCommerz-Händlerbereich):',
'StoreAdm_PG_Sslcommerz_Disabled_Desc' => 'Aktivieren Sie SSLCommerz und geben Sie Ihre Store-ID und Ihr Store-Passwort (aus dem SSLCommerz-Händlerbereich) ein, um im Online-Shop-Checkout Karten, Mobile Banking und Internetbanking zu akzeptieren.',
'StoreAdm_PG_Hours_Placeholder' => 'Mo-Sa 9:00-18:00',
