'Cr_Guide_Step_Test' => 'Verbindung testen',
'Cr_Guide_Step_Test_Help' => '„Verbindung testen“ prüft die Schlüssel und listet oft die Codes auf, die in den Kurieroptionen abgefragt werden.',
'Cr_Guide_Step_Webhook' => 'Webhook-URL registrieren',
'Cr_Guide_Step_Webhook_Help' => 'Kurierdienste, die Statusmeldungen senden, benötigen die Webhook-URL des Kontos (unten aufgeführt), damit sich Status sofort ändern. Die anderen werden nach Zeitplan abgefragt.',
'Cr_Guide_Step_Cod' => 'Ziel für Nachnahme-Auszahlungen wählen',
