'Cr_Guide_Good_To_Know' => 'Gut zu wissen',
'Cr_Guide_Webhooks' => 'Webhook-Adressen',
'Cr_Guide_How' => 'So registrieren Sie ihn',
'Cr_Guide_How_It_Works' => 'So funktioniert es',
'Cr_Guide_Meaning' => 'Bedeutung',
'Cr_Guide_T_Statuses' => 'Status',
'Cr_Guide_Statuses_Note' => 'Status bewegen sich nur vorwärts, sodass eine verspätete Meldung ein Paket nie zurücksetzt. Ein zugestelltes Paket kann dennoch als in Rücksendung oder retourniert gemeldet werden.',
'Cr_Guide_S_booked' => 'Der Kurierdienst hat die Bestellung; es wurde noch nichts abgeholt. Nur jetzt kann eine Buchung storniert werden.',
'Cr_Guide_S_picked_up' => 'Der Kurierdienst hat das Paket abgeholt.',
'Cr_Guide_S_in_transit' => 'Unterwegs zwischen Verteilzentren, im Zoll oder zurückgehalten.',
'Cr_Guide_S_out_for_delivery' => 'Heute beim Zusteller.',
'Cr_Guide_S_failed_attempt' => 'Nicht angetroffen, Annahme verweigert oder falsche Adresse. Der Kurierdienst versucht es erneut oder sendet es zurück.',
'Cr_Guide_S_delivered' => 'An den Kunden übergeben. Ein Nachnahmebetrag gilt als vom Kurierdienst eingezogen.',
'Cr_Guide_S_returning' => 'Auf dem Rückweg zu Ihnen.',
'Cr_Guide_S_returned' => 'Wieder bei Ihnen: Es wartet unter „Zu prüfende Retouren“ oder wird automatisch wieder eingelagert.',
'Cr_Guide_S_cancelled' => 'Die Buchung wurde storniert.',
'Cr_Guide_T_Booking' => 'Bestellungen buchen',
'Cr_Guide_B_Booking' => '„An Kurierdienst senden“ füllt das Formular aus dem Verkauf aus: Empfänger, Adresse, der noch offene Betrag als Nachnahme und das Gewicht der Produkte. Kurierdienste mit eigenen Städtelisten zeigen eine Auswahl an, und Ihre Wahl wird für diese Stadt gespeichert. Aggregatoren, DHL, FedEx, UPS und Lalamove bieten „Tarife vergleichen“: Wählen Sie einen Preis, und „Buchen“ kauft ihn. Mehrere Verkäufe können gleichzeitig aus der Verkaufsliste gebucht werden.',
'Cr_Guide_T_Cod' => 'Nachnahme',
'Cr_Guide_B_Cod' => 'Ein Nachnahmepaket wechselt von „Nicht eingezogen“ zu „Vom Kurierdienst eingezogen“ (bei Zustellung) zu „An Sie ausgezahlt“. Kurierdienste, die Auszahlungen melden, führen den letzten Schritt selbst aus; für die anderen verwenden Sie „Nachnahme aktualisieren“. Ist in den Kurier-Einstellungen ein Konto gewählt, wird eine Auszahlung als Zahlung zum Verkauf verbucht. Kuriergebühren können als Ausgabe gespeichert werden, sobald ein Paket abgeschlossen ist.',
'Cr_Guide_T_Returns' => 'Retournierte Pakete',
'Cr_Guide_B_Returns' => 'Standardmäßig wartet ein retourniertes Paket unter „Kurier-Sendungen“ im Bereich „Zu prüfende Retouren“. „Wieder einlagern“ erstellt eine Verkaufsretoure für die gesamte Bestellung und bucht die Artikel zurück in den Bestand; „Verwerfen“ bucht nichts zurück, für beschädigte oder verlorene Pakete. In den Kurier-Einstellungen kann stattdessen die automatische Wiedereinlagerung aktiviert werden.',
'Cr_Guide_T_Customers' => 'Kundennachrichten und Sendungsverfolgungsseite',
'Cr_Guide_B_Customers' => 'Die Kundenbenachrichtigungen in den Kurier-Einstellungen senden SMS, E-Mail oder WhatsApp bei den von Ihnen angehakten Status, jeweils einmal pro Paket und mit Ihrem eigenen Text. Die Sendungsverfolgungsseite in Ihrem Onlineshop ermöglicht Kunden, ein Paket per Sendungsnummer oder per Bestellnummer und Telefonnummer zu verfolgen. Kunden, die häufig Pakete zurücksenden, erhalten bei der Buchung eine Retourenrisiko-Kennzeichnung.',
'Cr_Guide_T_Labels' => 'Etiketten',
'Cr_Guide_B_Labels' => '„Etikett drucken“ liefert das eigene Etikett des Kurierdienstes, sofern er eines ausstellt (PDF, Link oder Bild), andernfalls ein Stocky-Etikett mit dem Sendungsbarcode und dem einzuziehenden Betrag. Erlauben Sie Pop-ups für diese Website, um drucken zu können. DHL, FedEx und UPS stellen ihr Etikett nur einmal bei der Buchung aus, und Stocky speichert es für Nachdrucke.',
'Cr_Guide_T_Faq' => 'Fehlerbehebung',
'Cr_Guide_Q_Test' => 'Verbindungstest schlägt fehl',
'Cr_Guide_A_Test' => 'Testschlüssel gehören zum Testmodus und Live-Schlüssel zum Live-Modus; sie sind unterschiedlich. Öffnen Sie die Kurier-Protokolle und lesen Sie die Antwort des Kurierdienstes, um den genauen Grund zu erfahren.',
'Cr_Guide_Q_City' => 'Der Kurierdienst lehnt die Stadt oder Adresse ab',
'Cr_Guide_A_City' => 'Wählen Sie die Stadt im Buchungsformular aus der Städteliste des Kurierdienstes; Kurierdienste akzeptieren nur ihre eigenen Bezeichnungen. Kurierdienste, die mit Postadressen arbeiten, benötigen außerdem Bundesland, Postleitzahl und den zweistelligen Ländercode.',
'Cr_Guide_Q_Webhook' => 'Status ändern sich nicht von selbst',
'Cr_Guide_A_Webhook' => 'Prüfen Sie bei Kurierdiensten mit Statusmeldungen, ob die Webhook-URL beim Kurierdienst registriert ist: Die Kurier-Protokolle zeigen jede empfangene Meldung oder den Grund für eine Ablehnung (zum Beispiel ein falsches Secret). Andere Kurierdienste werden nach dem Zeitplan in den Kurier-Einstellungen abgefragt, und „Status jetzt prüfen“ fragt sofort ab.',
'Cr_Guide_Q_Stuck' => 'Eine Sendung zeigt einen Fehler bei der Statusabfrage',
'Cr_Guide_A_Stuck' => 'Der Kurierdienst hat die letzten Abfragen abgelehnt; der Grund steht bei der Sendung und in den Kurier-Protokollen. Nach wiederholten Fehlschlägen wird eine Sendung nicht mehr automatisch abgefragt: Beheben Sie die Ursache und verwenden Sie dann „Status jetzt prüfen“.',
'Cr_Guide_Q_Label' => 'Beim Drucken eines Etiketts öffnet sich nichts',
'Cr_Guide_A_Label' => 'Ihr Browser hat das Pop-up blockiert. Erlauben Sie Pop-ups für diese Website und versuchen Sie es erneut.',
'Cr_Guide_Q_Cod' => 'Eine Nachnahme-Auszahlung wurde nicht beim Verkauf verbucht',
'Cr_Guide_A_Cod' => 'In den Kurier-Einstellungen muss für Nachnahme der Schalter aktiviert und ein Konto gewählt sein. Ohne Konto werden Auszahlungen nur als ausgezahlt markiert.',
