'Sec_2fa_Require' => 'Zwei-Faktor-Authentifizierung vorschreiben',
'Sec_2fa_Require_Help' => 'Mitarbeiter müssen nach ihrem Passwort einen Code aus einer Authenticator-App eingeben. Jeder kann sie für sich selbst im Profil aktivieren; diese Option macht sie verpflichtend. Benutzer ohne 2FA werden bei ihrer nächsten Anmeldung durch die Einrichtung geführt.',
