'Tfa_Download' => 'Herunterladen',
'Tfa_Done' => 'Fertig',
'Tfa_Codes_Save' => 'Bewahren Sie diese Wiederherstellungscodes an einem sicheren Ort auf. Jeder Code meldet Sie einmal an, falls Sie Ihr Telefon verlieren. Sie werden nicht erneut angezeigt.',
'Tfa_Reset' => 'Zwei-Faktor zurücksetzen',
'Tfa_Reset_Title' => 'Zwei-Faktor-Authentifizierung zurücksetzen?',
'Tfa_Reset_Help' => ':name meldet sich dann nur mit dem Passwort an und kann die Authenticator-App anschließend neu einrichten. Tun Sie dies nur, nachdem Sie bestätigt haben, wer die Anfrage stellt.',
'Tfa_Guide_Lead' => 'Die Zwei-Faktor-Authentifizierung (2FA) fügt der Anmeldung einen zweiten Schritt hinzu: Nach dem Passwort geben Mitarbeiter einen 6-stelligen Code aus einer Authenticator-App auf ihrem Telefon ein. Ein gestohlenes oder erratenes Passwort reicht dann nicht mehr für den Zugang aus.',
'Tfa_Guide_State_Required' => 'Vorgeschrieben',
'Tfa_Guide_State_Optional' => 'Nein — für alle optional',
'Tfa_Guide_State_Trust' => 'Vertrauenswürdige Geräte',
'Tfa_Guide_State_Users' => 'Benutzer mit aktivierter 2FA',
'Tfa_Guide_Staff_Title' => 'Für jeden Mitarbeiter',
'Tfa_Guide_App_Title' => 'Authenticator-App installieren',
'Tfa_Guide_App_Text' => 'Jede App, die standardmäßige 6-stellige Codes (TOTP) unterstützt, funktioniert. Sie sind kostenlos und funktionieren offline:',
'Tfa_Guide_Enable_Title' => 'Im Profil aktivieren',
'Tfa_Guide_Enable_1' => 'Öffnen Sie das Profil (Avatar-Menü oben rechts) und suchen Sie die Karte „Zwei-Faktor-Authentifizierung“.',
'Tfa_Guide_Enable_2' => 'Klicken Sie auf „Aktivieren“ und bestätigen Sie mit dem aktuellen Passwort.',
'Tfa_Guide_Enable_3' => 'Scannen Sie den QR-Code mit der App oder geben Sie den darunter angezeigten Schlüssel ein.',
'Tfa_Guide_Enable_4' => 'Geben Sie zum Abschließen den 6-stelligen Code ein, den die App anzeigt.',
'Tfa_Guide_Open_Profile' => 'Mein Profil öffnen',
'Tfa_Guide_Codes_Title' => 'Wiederherstellungscodes speichern',
'Tfa_Guide_Codes_Text' => 'Direkt nach der Einrichtung werden 8 Wiederherstellungscodes einmalig angezeigt. Jeder ersetzt genau einmal einen Telefoncode — bei einem verlorenen, defekten oder zurückgesetzten Telefon. Laden Sie sie herunter oder kopieren Sie sie und bewahren Sie sie an einem sicheren Ort getrennt vom Telefon auf.',
'Tfa_Guide_Codes_Note' => 'Gehen sie zur Neige? „Neue Wiederherstellungscodes“ im Profil ersetzt den gesamten Satz; die alten funktionieren dann nicht mehr.',
'Tfa_Guide_Signin_Title' => 'Anmeldung',
'Tfa_Guide_Signin_Text' => 'Nach E-Mail und Passwort fragt die Anmeldeseite nach dem aktuellen Code aus der App. Die Codes ändern sich alle 30 Sekunden und jeder funktioniert nur einmal.',
'Tfa_Guide_Signin_Trust' => 'Wird „Auf diesem Gerät nicht erneut fragen“ angehakt, entfällt der Code in diesem Browser für :days Tage.',
'Tfa_Guide_Signin_Recovery' => 'Kein Telefon zur Hand? Klicken Sie auf „Wiederherstellungscode verwenden“ und geben Sie einen der gespeicherten Codes ein.',
'Tfa_Guide_Admin_Title' => 'Für Administratoren',
'Tfa_Guide_Require_Title' => 'Verpflichtend machen',
'Tfa_Guide_Require_Text' => 'Aktivieren Sie auf dieser Karte „Zwei-Faktor-Authentifizierung vorschreiben“ und wählen Sie dann die Rollen, die sie verwenden müssen — oder lassen Sie die Liste für alle Benutzer leer. Klicken Sie zum Speichern auf „Absenden“.',
'Tfa_Guide_Require_Next' => 'Niemand wird abgemeldet. Benutzer, die noch keine 2FA haben, werden bei ihrer nächsten Anmeldung auf der Anmeldeseite durch die Einrichtung geführt, bevor sie Zugang erhalten, und sehen dort ihre Wiederherstellungscodes.',
'Tfa_Guide_Require_Note' => 'Benutzer, für die sie vorgeschrieben ist, können sie in ihrem Profil nicht deaktivieren.',
'Tfa_Guide_Trust_Title' => 'Vertrauenswürdige Geräte',
'Tfa_Guide_Trust_Text' => '„Vertrauenswürdige Geräte merken“ legt fest, wie lange ein Browser nach einer erfolgreichen Anmeldung den Code überspringen darf. Wählen Sie „Immer nach einem Code fragen“ für gemeinsam genutzte oder öffentliche Computer, z. B. eine POS-Kasse im Verkaufsraum.',
'Tfa_Guide_Trust_Note' => 'Eine Verringerung der Anzahl verkürzt auch die Dauer bereits vertrauenswürdiger Geräte; durch Deaktivieren oder Zurücksetzen der 2FA werden alle vergessen.',
'Tfa_Guide_Lost_Title' => 'Telefon verloren und keine Wiederherstellungscodes',
'Tfa_Guide_Lost_Text' => 'Auf der Benutzerseite zeigen Benutzer mit 2FA in der Spalte 2FA „Ein“ an. Die Schild-Schaltfläche unter Aktionen setzt sie zurück: Der Benutzer meldet sich nur mit dem Passwort an und richtet die App erneut ein (oder wird dazu aufgefordert, falls sie vorgeschrieben ist).',
'Tfa_Guide_Lost_Warn' => 'Bestätigen Sie vor dem Zurücksetzen, wer die Anfrage stellt — ein Zurücksetzen hebt den Schutz auf, den die 2FA diesem Konto bietet.',
'Tfa_Guide_Open_Users' => 'Benutzer öffnen',
'Tfa_Guide_Mobile_Title' => 'Mobile App und API',
'Tfa_Guide_Mobile_Text' => 'Die mobile App und der API-Token-Endpunkt fragen denselben Code ab. Ist 2FA für einen Benutzer vorgeschrieben, der sie noch nicht eingerichtet hat, muss er sich dazu einmal im Web anmelden.',
'Tfa_Guide_Protect_Title' => 'Integrierter Schutz',
'Tfa_Guide_Protect_1' => '5 falsche Codes sperren die Code-Eingabe für diesen Benutzer für 15 Minuten, unabhängig von den obigen Sperreinstellungen.',
'Tfa_Guide_Protect_2' => 'Jeder Code und jeder Wiederherstellungscode funktioniert nur einmal.',
'Tfa_Guide_Protect_3' => 'Ist „Anmeldeaktivität aufzeichnen“ aktiviert, erscheinen falsche Codes in der Liste der Anmeldeaktivitäten als „Falscher 2FA-Code“.',
'Tfa_Guide_Trouble_Title' => 'Fehlerbehebung',
'Tfa_Guide_Faq_Clock_Q' => '„Dieser Code ist ungültig“ trotz neuem Code',
'Tfa_Guide_Faq_Clock_A' => 'Die Uhr des Telefons geht vermutlich falsch. Die Codes hängen von der Uhrzeit ab: Stellen Sie Datum und Uhrzeit des Telefons auf automatisch (Netzwerkzeit) und versuchen Sie dann den nächsten Code.',
'Tfa_Guide_Faq_Phone_Q' => 'Wechsel auf ein neues Telefon',
'Tfa_Guide_Faq_Phone_A' => 'Verwenden Sie entweder die Übertragungsfunktion der Authenticator-App oder deaktivieren Sie 2FA im Profil und aktivieren Sie sie mit dem neuen Telefon erneut (falls sie vorgeschrieben ist, bitten Sie stattdessen einen Administrator, sie zurückzusetzen).',
'Tfa_Guide_Faq_Locked_Q' => '„Zu viele ungültige Codes“',
'Tfa_Guide_Faq_Locked_A' => 'Warten Sie die angezeigte Zeit ab (bis zu 15 Minuten) oder lassen Sie einen Administrator die 2FA des Benutzers zurücksetzen.',
'Tfa_Guide_Faq_Key_Q' => 'Nach einem Serverumzug kann sich niemand mit 2FA anmelden',
'Tfa_Guide_Faq_Key_A' => 'Die 2FA-Geheimnisse sind mit dem APP_KEY aus der .env-Datei verschlüsselt. Behalten Sie beim Umzug oder bei der Wiederherstellung der Anwendung denselben APP_KEY bei; wurde er geändert, muss ein Administrator ohne 2FA die betroffenen Benutzer zurücksetzen.',
'Tfa_Guide_Button' => 'Leitfaden',
'Tfa_Guide_Title' => 'Leitfaden zur Zwei-Faktor-Authentifizierung',
'Sec_2fa_Pending' => ':count müssen sie noch einrichten',
'Sec_2fa_See_Who' => 'Anzeigen, wer',
'Sec_2fa_Grace_Off' => 'Keine — Einrichtung bei der nächsten Anmeldung',
'Sec_2fa_Applied' => ':count Benutzer abgemeldet.',
'Tfa_Guide_Rollout_Title' => 'Für alle Benutzer einführen',
'Tfa_Guide_Rollout_1' => 'Aktivieren Sie sie zuerst für Ihr eigenes Konto (Profil), damit Sie die Schritte kennen.',
'Tfa_Guide_Rollout_2' => 'Teilen Sie Ihrem Team mit, welche App installiert werden soll und dass die Einrichtung bei der Anmeldung eine Minute dauert.',
'Tfa_Guide_Rollout_3' => 'Aktivieren Sie „Zwei-Faktor-Authentifizierung vorschreiben“, lassen Sie „Erforderlich für“ leer (= alle Benutzer) und wählen Sie optional eine Übergangsfrist. Klicken Sie auf „Absenden“.',
'Tfa_Guide_Rollout_4' => 'Klicken Sie auf „Benutzer ohne 2FA abmelden“, damit bereits angemeldete Personen sie jetzt einrichten statt erst bei einer späteren Anmeldung. Sie selbst bleiben angemeldet.',
'Tfa_Guide_Rollout_5' => 'Verfolgen Sie den Fortschritt mit dem Zähler auf dieser Karte oder mit dem Filter „Einrichtung erforderlich“ auf der Benutzerseite.',
'Tfa_Guide_Rollout_Note' => 'Mit einer Übergangsfrist zeigt der Einrichtungsbildschirm bis zum Stichtag „Später erinnern“ an; danach ist die Einrichtung für die Anmeldung erforderlich.',
'Tfa_Guide_Customers_Title' => 'Kundenkonten (Shop und Kundenportal)',
'Tfa_Guide_Customers_Text' => 'Auch Kunden können ihre eigenen Konten schützen. Dies ist für jeden Kunden optional und wird nie erzwungen: Aktivieren Sie es unter Shop-Einstellungen → Registrierungs-Zugriffskontrolle (Onlineshop) und Kundenportal → Portal-Einstellungen (Kundenportal).',
'Tfa_Guide_Customers_1' => 'Kunden aktivieren es unter „Mein Konto“ (Shop) oder „Profil“ (Portal).',
'Tfa_Guide_Customers_2' => 'Sie wählen einen per E-Mail gesendeten Code — am einfachsten, keine App nötig — oder eine Authenticator-App mit Wiederherstellungscodes.',
'Tfa_Guide_Customers_3' => 'Per E-Mail gesendete Codes erfordern funktionierende Mail-Einstellungen (Einstellungen → Mail-Einstellungen). Sie laufen nach 10 Minuten ab.',
'Tfa_Guide_Customers_4' => 'Wird die Option später deaktiviert, sind keine neuen Einrichtungen mehr möglich; Kunden, die sie bereits nutzen, werden weiterhin abgefragt und können sie selbst deaktivieren.',
'Tfa_Required_Grace_Notice' => 'Ihr Administrator schreibt die Zwei-Faktor-Authentifizierung vor. Sie können sie bei der Anmeldung bis :date aufschieben; danach ist die Einrichtung erforderlich.',
'Tfa_Filter_All' => '2FA: alle Benutzer',
'Tfa_Needs_Setup_Help' => 'Vorgeschrieben durch Systemeinstellungen > Sicherheit; wird bei der nächsten Anmeldung zur Einrichtung aufgefordert.',
'Tfa_Needs_Setup' => 'Einrichtung erforderlich',
'Tfa_Filter_On' => '2FA ein',
'Tfa_Filter_Off' => '2FA aus',
'Tfa_Filter_Pending' => 'Einrichtung erforderlich (vorgeschrieben)',
'Store_Customer_2fa' => 'Zweistufige Verifizierung',
'Store_Customer_2fa_Help' => 'Ermöglicht Kunden, ihr Konto mit einem per E-Mail gesendeten Code oder einem Code aus einer Authenticator-App zu schützen; die Aktivierung erfolgt unter „Mein Konto“. Für jeden Kunden optional.',
'Portal_2fa' => 'Zweistufige Verifizierung',
'Portal_2fa_Help' => 'Ermöglicht Kunden, ihren Portal-Login mit einem per E-Mail gesendeten Code oder einem Code aus einer Authenticator-App zu schützen; die Aktivierung erfolgt in ihrem Profil. Für jeden Kunden optional.',
'Two_factor_grace_notice' => 'Erforderlich ab :date. Bis dahin können Sie die Einrichtung aufschieben.',
'Two_factor_remind_later' => 'Später erinnern',
'Sec_2fa_Grace' => 'Übergangsfrist',
'Sec_2fa_Grace_Help' => 'Ermöglicht Benutzern, auf dem Einrichtungsbildschirm bis zum Stichtag „Später erinnern“ zu wählen, damit niemand mitten in einer Schicht aufgehalten wird. Gerechnet ab dem Zeitpunkt, an dem die Pflicht aktiviert wurde.',
